import React, { useEffect, useRef, useState } from "react";
import { createRoot } from "react-dom/client";
import World from "../components/world";
import { useOrb } from "../lib/store";
import { projectSchema } from "../lib/protocol";
import "./player.css";
import { configureGeneratedGeometryResolver } from "../lib/use-generated-geometry";
import {
  beginPlayerPointerInput,
  endPlayerPointerInput,
} from "../lib/player-input";
import {
  generatedModelPath,
  MAX_GENERATED_MODEL_BYTES,
} from "../lib/generated-models";
import { playerControlsHelp } from "../lib/player-controls";
import { GraphicsGuidance } from "../components/graphics-guidance";
configureGeneratedGeometryResolver(async (hash, signal) => {
  const response = await fetch(`./${generatedModelPath(hash)}`, {
    signal,
    redirect: "error",
    credentials: "omit",
  });
  if (!response.ok || !response.body)
    throw Error("This world's generated model is missing.");
  const reader = response.body.getReader();
  const chunks: Uint8Array[] = [];
  let size = 0;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > MAX_GENERATED_MODEL_BYTES)
        throw Error("The generated model exceeds its size budget.");
      chunks.push(value);
    }
  } catch (error) {
    await reader.cancel().catch(() => undefined);
    throw error;
  } finally {
    reader.releaseLock();
  }
  const bytes = new Uint8Array(size);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.length;
  }
  return bytes;
});
function PlayerApp() {
  const s = useOrb();
  const [error, setError] = useState("");
  const [graphicsError, setGraphicsError] = useState("");
  const [graphicsHelpVisible, setGraphicsHelpVisible] = useState(false);
  const [softwareRenderer, setSoftwareRenderer] = useState(false);
  const [rendererRetryToken, setRendererRetryToken] = useState(0);
  const [rendererReady, setRendererReady] = useState(false);
  const [sceneReady, setSceneReady] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [touchDevice, setTouchDevice] = useState(false);
  const gameplayRegion = useRef<HTMLDivElement>(null);
  const focusGameplayRegion = () =>
    gameplayRegion.current?.focus({ preventScroll: true });
  const resetGame = () => {
    s.set({
      score: [],
      gameScore: 0,
      won: false,
      lost: false,
      reset: s.reset + 1,
    });
    focusGameplayRegion();
  };
  const ready = rendererReady && sceneReady;
  const retryRenderer = () => {
    if (!graphicsError) return;
    setGraphicsError("");
    setGraphicsHelpVisible(false);
    setSoftwareRenderer(false);
    setRendererReady(false);
    setSceneReady(false);
    setRendererRetryToken((token) => token + 1);
  };
  const collectibles = s.project.entities.filter(
    (e) => e.stage === "ready" && e.behavior?.type === "collect",
  );
  useEffect(() => {
    fetch("./project.json")
      .then((r) => {
        if (!r.ok) throw Error("Could not open this world.");
        return r.json();
      })
      .then((p) => {
        s.load(projectSchema.parse(p), true);
        s.set({ readOnly: true });
        setLoaded(true);
      })
      .catch((e) => setError(e.message));
  }, []);
  useEffect(() => {
    const media = window.matchMedia("(any-pointer: coarse)");
    const update = () =>
      setTouchDevice(media.matches || navigator.maxTouchPoints > 0);
    update();
    media.addEventListener?.("change", update);
    return () => media.removeEventListener?.("change", update);
  }, []);
  return (
    <main
      className={touchDevice ? "touch-layout" : undefined}
      data-ready={ready && !error}
    >
      <div
        ref={gameplayRegion}
        className="canvas gameplay-region"
        role="region"
        aria-label="Gameplay area"
        tabIndex={-1}
      >
        {loaded && (
          <World
            key={rendererRetryToken}
            rendererRetryToken={rendererRetryToken}
            onReady={() => setSceneReady(true)}
            onRendererReady={(renderer) => {
              setRendererReady(true);
              if (renderer === "webgl") {
                setGraphicsError("");
                setGraphicsHelpVisible(false);
                setSoftwareRenderer(false);
              }
            }}
            onRendererFallback={(message) => {
              setGraphicsError(message);
              setGraphicsHelpVisible(true);
              setSoftwareRenderer(true);
            }}
            onError={(message) => {
              setGraphicsError(message);
              setGraphicsHelpVisible(true);
              setSoftwareRenderer(false);
              setRendererReady(false);
              setSceneReady(false);
            }}
          />
        )}
      </div>
      <header>
        <a href="https://orbsie.com">◉ orbsie</a>
        <span>{s.project.title}</span>
        <button onClick={resetGame}>↻ Restart</button>
      </header>
      {graphicsError && graphicsHelpVisible ? (
        <div className="message graphics-player-error" role="status">
          <GraphicsGuidance
            standalone
            advisory={softwareRenderer}
            detail={graphicsError}
            onRetry={retryRenderer}
            onDismiss={
              softwareRenderer ? () => setGraphicsHelpVisible(false) : undefined
            }
          />
        </div>
      ) : (
        (!ready || error) && (
          <div className="message">{error || "Opening your little world…"}</div>
        )
      )}
      <div
        className="score"
        hidden={
          !ready ||
          Boolean(error) ||
          (!softwareRenderer && Boolean(graphicsError))
        }
      >
        {s.project.game ? (
          `Score: ${s.gameScore}`
        ) : (
          <>
            ◆ {collectibles.filter((e) => s.score.includes(e.id)).length} /{" "}
            {collectibles.length}
          </>
        )}
      </div>
      <footer>{playerControlsHelp(s.project, touchDevice)}</footer>
      <div className="controls">
        {["w", "a", "s", "d", " "].map((key, i) => (
          <button
            key={key}
            aria-label={["Forward", "Left", "Back", "Right", "Jump"][i]}
            onPointerDown={(e) => beginPlayerPointerInput(e, key)}
            onPointerUp={(e) => endPlayerPointerInput(e, key)}
            onPointerCancel={(e) => endPlayerPointerInput(e, key)}
            onLostPointerCapture={(e) => endPlayerPointerInput(e, key)}
          >
            {["↑", "←", "↓", "→", "↗"][i]}
          </button>
        ))}
      </div>
      {(s.won || s.lost) && (
        <div className="win">
          <h1>{s.lost ? "Try another adventure" : "Adventure complete"}</h1>
          <p>
            {s.project.game
              ? `Final score: ${s.gameScore}`
              : "You found every crystal and made it home."}
          </p>
          <button onClick={resetGame}>Play again</button>
        </div>
      )}
    </main>
  );
}
createRoot(document.getElementById("root")!).render(<PlayerApp />);

src/player/player.css:
* {
  box-sizing: border-box;
}
body {
  margin: 0;
  font-family: system-ui, sans-serif;
  color: #31594c;
  background: #e5eee0;
}
main {
  height: 100dvh;
  overflow: hidden;
  background: radial-gradient(ellipse at 45% 25%, #fff8e4, #d0e8df);
  --player-safe-top: env(safe-area-inset-top, 0px);
  --player-safe-right: env(safe-area-inset-right, 0px);
  --player-safe-bottom: env(safe-area-inset-bottom, 0px);
  --player-safe-left: env(safe-area-inset-left, 0px);
}
.canvas {
  position: absolute;
  inset: 0;
}
.gameplay-region:focus-visible {
  outline: 3px solid #a184cc;
  outline-offset: -3px;
}
header {
  position: absolute;
  left: calc(25px + var(--player-safe-left));
  right: calc(25px + var(--player-safe-right));
  top: calc(22px + var(--player-safe-top));
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  font-size: 13px;
}
a {
  color: inherit;
  text-decoration: none;
  font-size: 23px;
  font-weight: 700;
}
button {
  cursor: pointer;
  border: 1px solid #ffffff80;
  background: #faffeecc;
  color: #31594c;
  border-radius: 12px;
  padding: 12px 18px;
}
header span {
  margin-right: auto;
}
.score {
  position: absolute;
  top: calc(82px + var(--player-safe-top));
  right: calc(25px + var(--player-safe-right));
  background: #ffffeccc;
  border-radius: 14px;
  padding: 15px;
}
footer {
  position: absolute;
  bottom: calc(24px + var(--player-safe-bottom));
  left: var(--player-safe-left);
  right: var(--player-safe-right);
  text-align: center;
  font-size: 11px;
  color: #6e8d7b;
  pointer-events: none;
}
.win,
.message {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  background: #fffff0ed;
  border-radius: 20px;
  padding: 30px;
  text-align: center;
  min-width: 300px;
}
.graphics-player-error {
  width: min(520px, calc(100% - 32px));
  max-height: calc(100dvh - 48px);
  overflow: auto;
  padding: 24px;
}
.graphics-guidance {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 9px;
  text-align: left;
}
.graphics-guidance h2 {
  margin: 0;
  font-size: 18px;
  line-height: 1.25;
}
.graphics-guidance > p {
  margin: 0;
  font-size: 12px;
  line-height: 1.45;
}
.graphics-guidance-detail {
  overflow-wrap: anywhere;
  color: #8a6558;
}
.graphics-guidance ol {
  margin: 0 0 0 19px;
  padding: 0;
  font-size: 12px;
  line-height: 1.5;
}
.graphics-guidance details {
  font-size: 11px;
  line-height: 1.5;
}
.graphics-guidance summary {
  cursor: pointer;
  font-weight: 600;
}
.graphics-guidance details p {
  margin: 8px 0 0;
  font-size: 11px;
}
.graphics-guidance-warning {
  font-size: 11px !important;
}
.graphics-guidance button {
  border: 1px solid currentColor;
  border-radius: 8px;
  background: transparent;
  padding: 6px 9px;
  font-size: 11px;
  margin-left: 6px;
}
.graphics-guidance-retry {
  align-self: center;
  background: #d4e8aa;
  color: #285d4d;
  font-weight: 600;
}
.graphics-guidance-dismiss {
  align-self: center;
  border-color: transparent;
  padding: 4px 8px;
  font-weight: 500;
}
.win h1 {
  font-size: 29px;
  font-weight: 500;
  letter-spacing: -1px;
}
.win p {
  font-size: 12px;
}
.controls {
  display: none;
}
.webgl-fallback {
  position: absolute;
  top: 40%;
  left: 10%;
  right: 10%;
  text-align: center;
}
main.touch-layout header {
  left: calc(15px + var(--player-safe-left));
  right: calc(15px + var(--player-safe-right));
}
main.touch-layout header span {
  font-size: 10px;
}
main.touch-layout .controls {
  display: flex;
  position: absolute;
  bottom: calc(30px + var(--player-safe-bottom));
  left: calc(20px + var(--player-safe-left));
  right: calc(20px + var(--player-safe-right));
  gap: 6px;
}
main.touch-layout .controls button {
  width: 45px;
  height: 45px;
  padding: 0;
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
  font-size: 20px;
}
main.touch-layout .controls button:last-child {
  margin-left: auto;
}
main.touch-layout footer {
  bottom: calc(90px + var(--player-safe-bottom));
  font-size: 9px;
}
@media (max-width: 700px) and (pointer: fine),
  (max-width: 700px) and (pointer: none) {
  header {
    left: calc(15px + var(--player-safe-left));
    right: calc(15px + var(--player-safe-right));
  }
  header span {
    font-size: 10px;
  }
  footer {
    font-size: 10px;
  }
}

/* Compatibility mode is playable; its advice must not cover the game. */
.graphics-guidance.is-advisory {
  flex-direction: row;
  align-items: start;
  gap: 12px;
}
.graphics-guidance.is-advisory details {
  flex: 1;
  margin: 0;
  font-size: 12px;
}
.graphics-guidance.is-advisory > button {
  padding: 0 4px;
  font-size: 18px;
  line-height: 1;
}
.graphics-error.is-advisory {
  width: min(360px, calc(100% - 32px));
  padding: 10px 14px;
}
.graphics-player-error:has(.is-advisory) {
  top: calc(144px + var(--player-safe-top));
  transform: translateX(-50%);
  width: min(360px, calc(100% - 32px));
  min-width: 0;
  padding: 10px 14px;
}
.software-world {
  position: absolute;
  inset: 0;
  overflow: hidden;
}
.world-navigation-controls {
  position: absolute;
  z-index: 8;
  top: 50%;
  right: calc(18px + var(--player-safe-right, 0px));
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 6px;
  border: 1px solid #ffffffc9;
  border-radius: 15px;
  background: #fffff0d9;
  box-shadow: 0 9px 26px #294c3b1a;
  backdrop-filter: blur(12px);
  transform: translateY(-50%);
}
.world-navigation-controls > button {
  display: flex;
  width: 76px;
  min-height: 44px;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 5px;
  border: 1px solid #d1dfcf;
  border-radius: 11px;
  background: #f8fbef;
  color: #31594c;
  font-size: 10px;
  font-variant-numeric: tabular-nums;
  touch-action: manipulation;
}
.world-navigation-controls > button:hover:not(:disabled) {
  background: #e8f0dc;
}
.world-navigation-controls > button:focus-visible {
  outline: 3px solid #8d70bd;
  outline-offset: 2px;
  z-index: 1;
}
.world-navigation-controls > button:disabled {
  cursor: wait;
  opacity: 0.62;
}
.world-navigation-compass > span {
  min-width: 30px;
}
.world-navigation-north-arrow {
  width: 16px;
  height: 16px;
  fill: #47785e;
  transition: transform 160ms ease-out;
}
.world-navigation-notice:not(:empty) {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  width: max-content;
  max-width: min(260px, calc(100vw - 24px));
  padding: 8px 10px;
  border: 1px solid #dfc7aa;
  border-radius: 9px;
  background: #fffaf0;
  box-shadow: 0 5px 18px #294c3b1a;
  color: #775e43;
  font-size: 10px;
  line-height: 1.4;
}
@media (orientation: landscape) and (max-height: 600px) and (pointer: coarse) {
  main.touch-layout footer {
    display: none;
  }
  .graphics-player-error:has(.is-advisory) {
    top: auto;
    bottom: calc(86px + var(--player-safe-bottom));
  }
  .world-navigation-controls {
    top: auto;
    right: auto;
    bottom: calc(max(43dvh, 140px) + 16px + var(--player-safe-bottom, 0px));
    left: 50%;
    flex-direction: row;
    gap: 2px;
    padding: 4px;
    transform: translateX(-50%);
  }
  .world-navigation-controls > button {
    width: 64px;
    min-height: 44px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .world-navigation-north-arrow {
    transition: none;
  }
}
.software-world canvas {
  display: block;
  width: 100%;
  height: 100%;
}
.software-world-status {
  display: none;
}

