  type SceneReviewSourceState,
} from "@/lib/scene-review-capture";
import type { Entity, Project } from "@/lib/protocol";
import { GameSession, GAME_RULES_RESTART_NOTICE } from "@/lib/game-session";
import {
  PlayerInputTracker,
