function navigationZoomLabel(state: WorldNavigationProjectState["navigation"]) {
  const percent = (WORLD_NAVIGATION_DEFAULT_DISTANCE / state.distance) * 100;
  if (!Number.isFinite(percent) || percent < 0.01) return "<0.01%";
