      ? project.entities.find((e) => e.id === "platform-1")
      : project.entities.find((e) => e.id === selected)) ??
    project.entities.find((e) =>
      p.includes("platform")
        ? e.id === "platform-1"
        : e.geometry?.kind === "tree",
    );
