import * as THREE from "three";
import { mergeGeometries } from "three/addons/utils/BufferGeometryUtils.js";
import type { Entity } from "./protocol";
export function entityGeometry(entity: Entity): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const tint =
    entity.geometry?.kind !== "asset" && entity.geometry?.kind !== "generated"
      ? entity.geometry?.tint
      : undefined;
  const coarse = entity.geometry?.detail === "coarse";
  const segments = coarse ? 6 : 14;
  const add = (
    g: THREE.BufferGeometry,
    p = [0, 0, 0],
    s = [1, 1, 1],
    color = entity.color,
    r = [0, 0, 0],
  ) => {
    let geometry = g.index ? g.toNonIndexed() : g;
    if (geometry !== g) g.dispose();
    geometry.deleteAttribute("uv");
    geometry.applyMatrix4(
      new THREE.Matrix4().compose(
        new THREE.Vector3(...p),
        new THREE.Quaternion().setFromEuler(
          new THREE.Euler(...(r as [number, number, number])),
        ),
        new THREE.Vector3(...s),
      ),
    );
    const c = new THREE.Color(tint ?? color);
    const colors = new Float32Array(geometry.attributes.position.count * 3);
    for (let i = 0; i < colors.length; i += 3) {
      colors[i] = c.r;
      colors[i + 1] = c.g;
      colors[i + 2] = c.b;
    }
    geometry.setAttribute("color", new THREE.BufferAttribute(colors, 3));
    parts.push(geometry);
  };
  const sphere = (p: number[], s: number[], c = entity.color) =>
    add(new THREE.SphereGeometry(1, segments, segments), p, s, c);
  const cylinder = (p: number[], s: number[], c = entity.color) =>
    add(new THREE.CylinderGeometry(0.65, 1, 1, segments), p, s, c);
  switch (entity.geometry?.kind) {
    case "tree":
      cylinder([0, 0.8, 0], [0.2, 1.6, 0.2], "#98775a");
      sphere([0, 2, 0], [0.95, 1.05, 0.9]);
      if (!coarse) {
        sphere([-0.55, 1.65, 0.15], [0.6, 0.75, 0.6]);
        sphere([0.55, 1.9, 0.15], [0.55, 0.7, 0.55]);
      }
      break;
    case "mushroom":
      cylinder([0, 0.7, 0], [0.25, 1.4, 0.25], "#f6ebd3");
      sphere([0, 1.5, 0], [1.15, 0.65, 1.15]);
      if (!coarse)
        for (let i = 0; i < 7; i++)
          sphere(
            [
              Math.cos(i * 2.4) * 0.7,
              1.94 + Math.sin(i) * 0.05,
              Math.sin(i * 2.4) * 0.7,
            ],
            [0.13, 0.045, 0.13],
            "#fff1de",
          );
      break;
    case "platform":
      add(new THREE.BoxGeometry(1, 0.45, 1, 2, 2, 2), [0, 0.2, 0]);
      add(
        new THREE.BoxGeometry(0.9, 0.1, 0.9),
        [0, 0.47, 0],
        [1, 1, 1],
        "#fff2cf",
      );
      break;
    case "arch":
      for (const x of [-0.8, 0.8]) {
        cylinder([x, 1, 0], [0.24, 2, 0.25]);
        add(new THREE.BoxGeometry(0.65, 0.2, 0.65), [x, 0.1, 0]);
      }
      add(new THREE.TorusGeometry(0.8, 0.23, 8, 24, Math.PI), [0, 1.85, 0]);
      if (!coarse) sphere([0, 2.75, 0], [0.16, 0.16, 0.16], "#f8d88d");
      break;
    case "crystal":
      add(
        new THREE.OctahedronGeometry(0.65, 0),
        [0, 0.5, 0],
        [0.65, 1.25, 0.65],
      );
      break;
    case "pond":
      cylinder([0, 0.02, 0], [1.3, 0.055, 1], "#d3d7a8");
      cylinder([0, 0.06, 0], [1.2, 0.065, 0.9], entity.color);
      break;
    case "flower":
      cylinder([0, 0.5, 0], [0.055, 1, 0.055], "#779963");
      for (let i = 0; i < (coarse ? 4 : 7); i++) {
        const a = (i * Math.PI * 2) / (coarse ? 4 : 7);
        sphere(
          [Math.cos(a) * 0.3, 1.04, Math.sin(a) * 0.3],
          [0.26, 0.15, 0.26],
        );
      }
      sphere([0, 1.12, 0], [0.19, 0.13, 0.19], "#ffdf92");
      sphere([0.19, 0.4, 0], [0.3, 0.08, 0.12], "#91b878");
      break;
    case "rock":
      sphere([0, 0.35, 0], [0.7, 0.55, 0.6]);
      sphere([0.55, 0.18, 0.15], [0.35, 0.3, 0.4]);
      break;
    case "custom":
      break;
    default:
      sphere([0, 0.65, 0], [0.5, 0.5, 0.5], "#bceee0");
  }
  if (
    entity.geometry &&
    entity.geometry.kind !== "asset" &&
    entity.geometry.kind !== "generated"
  ) {
    for (const part of entity.geometry.parts ?? []) {
      const g =
        part.shape === "lathe"
          ? new THREE.LatheGeometry(
              part.profile.map(
                ([radius, height]) => new THREE.Vector2(radius, height),
              ),
              segments,
            )
          : part.shape === "box"
            ? new THREE.BoxGeometry(1, 1, 1, 2, 2, 2)
            : part.shape === "cone"
              ? new THREE.ConeGeometry(1, 1, segments)
              : part.shape === "cylinder"
                ? new THREE.CylinderGeometry(1, 1, 1, segments)
                : part.shape === "torus"
                  ? new THREE.TorusGeometry(0.7, 0.25, 8, segments)
                  : new THREE.SphereGeometry(1, segments, segments);
      add(g, part.position, part.scale, part.color, part.rotation);
    }
  }
  if (!parts.length) sphere([0, 0.5, 0], [0.5, 0.5, 0.5]);
  const merged = mergeGeometries(parts);
  parts.forEach((g) => g.dispose());
  merged.computeBoundingSphere();
  return merged;
}
export interface FormationSnapshot {
  positions: Float32Array;
  colors: Float32Array;
}

function validTriplets(values: unknown): values is Float32Array {
  return (
    values instanceof Float32Array &&
    values.length > 0 &&
    values.length % 3 === 0 &&
    values.every((value) => Number.isFinite(value))
  );
}

type FormationAttribute =
  THREE.BufferAttribute | THREE.InterleavedBufferAttribute;

function finiteAttribute(
  attribute: FormationAttribute | undefined,
  count: number,
  fallback: number,
) {
  const values = new Float32Array(count * 3);
  if (!attribute || attribute.count !== count || attribute.itemSize < 3) {
    values.fill(fallback);
    return values;
  }
  for (let index = 0; index < count; index++) {
    const targetIndex = index * 3;
    const x = attribute.getX(index);
    const y = attribute.getY(index);
    const z = attribute.getZ(index);
    values[targetIndex] = Number.isFinite(x) ? x : fallback;
    values[targetIndex + 1] = Number.isFinite(y) ? y : fallback;
    values[targetIndex + 2] = Number.isFinite(z) ? z : fallback;
  }
  return values;
}

function validFormationAttribute(
  attribute: FormationAttribute | undefined,
  count: number,
) {
  if (!attribute || attribute.count !== count || attribute.itemSize < 3)
    return false;
  for (let index = 0; index < count; index++) {
    if (
      !Number.isFinite(attribute.getX(index)) ||
      !Number.isFinite(attribute.getY(index)) ||
      !Number.isFinite(attribute.getZ(index))
    )
      return false;
  }
  return true;
}

function formationEase(progress: number) {
  if (!Number.isFinite(progress)) return 1;
  const clamped = Math.min(1, Math.max(0, progress));
  return clamped * clamped * (3 - 2 * clamped);
}

export function captureFormationSnapshot(
  geometry: THREE.BufferGeometry,
  progress: number,
): FormationSnapshot {
  const positionAttribute = geometry.getAttribute("position");
  const count = positionAttribute?.count ?? 0;
  const positions = finiteAttribute(positionAttribute, count, 0);
  const colors = finiteAttribute(geometry.getAttribute("color"), count, 1);
  const fromPositions = finiteAttribute(
    geometry.getAttribute("aFrom"),
    count,
    0,
  );
  const fromColors = finiteAttribute(
    geometry.getAttribute("aFromColor"),
    count,
    1,
  );
  const fromPositionAttribute = geometry.getAttribute("aFrom");
  const fromColorAttribute = geometry.getAttribute("aFromColor");
  const positionSource = validFormationAttribute(fromPositionAttribute, count)
    ? fromPositions
    : positions;
  const colorSource = validFormationAttribute(fromColorAttribute, count)
    ? fromColors
    : colors;
  const ease = formationEase(progress);
  if (ease === 0)
    return {
      positions: positionSource.slice(),
      colors: colorSource.slice(),
    };
  if (ease === 1)
    return { positions: positions.slice(), colors: colors.slice() };
  const visiblePositions = new Float32Array(positions.length);
  const visibleColors = new Float32Array(colors.length);
  for (let index = 0; index < positions.length; index++)
    visiblePositions[index] =
      positionSource[index] + (positions[index] - positionSource[index]) * ease;
  for (let index = 0; index < colors.length; index++)
    visibleColors[index] =
      colorSource[index] + (colors[index] - colorSource[index]) * ease;
  return { positions: visiblePositions, colors: visibleColors };
}

export function addFormationSource(
  geometry: THREE.BufferGeometry,
  previous?: Float32Array | FormationSnapshot,
) {
  const position = geometry.getAttribute("position");
  const count = position?.count ?? 0;
  const targetPositions = finiteAttribute(position, count, 0);
  const targetColors = finiteAttribute(
    geometry.getAttribute("color"),
    count,
    1,
  );
  const snapshot =
    previous && !(previous instanceof Float32Array) ? previous : undefined;
  const previousPositions = snapshot?.positions ?? previous;
  const previousColors = snapshot?.colors;
  const hasPreviousPositions = validTriplets(previousPositions);
  const hasPreviousColors = validTriplets(previousColors);
  const previousPositionCount = hasPreviousPositions
    ? previousPositions.length / 3
    : 0;
  const previousColorCount = hasPreviousColors ? previousColors.length / 3 : 0;
  const matchingPreviousColors =
    snapshot &&
    hasPreviousPositions &&
    hasPreviousColors &&
    previousColorCount === previousPositionCount;
  const source = new Float32Array(targetPositions.length);
  const sourceColors = new Float32Array(targetColors.length);
  sourceColors.set(targetColors);
  for (let index = 0; index < count; index++) {
    const targetIndex = index * 3;
    if (hasPreviousPositions) {
      const sourceCount = previousPositionCount;
      const sourceIndex = (index % Math.max(1, sourceCount)) * 3;
      source[targetIndex] = previousPositions[sourceIndex];
      source[targetIndex + 1] = previousPositions[sourceIndex + 1];
      source[targetIndex + 2] = previousPositions[sourceIndex + 2];
    } else if (!previous) {
      const y = count ? 1 - (2 * (index + 0.5)) / count : 0;
      const a = index * 2.399963;
      const r = Math.sqrt(Math.max(0, 1 - y * y)) * 0.58;
      source[targetIndex] = Math.cos(a) * r;
      source[targetIndex + 1] = y * 0.58 + 0.7;
      source[targetIndex + 2] = Math.sin(a) * r;
    } else {
      source[targetIndex] = targetPositions[targetIndex];
      source[targetIndex + 1] = targetPositions[targetIndex + 1];
      source[targetIndex + 2] = targetPositions[targetIndex + 2];
    }
    if (matchingPreviousColors && previousColors) {
      const sourceIndex = (index % previousColorCount) * 3;
      sourceColors[targetIndex] = previousColors[sourceIndex];
      sourceColors[targetIndex + 1] = previousColors[sourceIndex + 1];
      sourceColors[targetIndex + 2] = previousColors[sourceIndex + 2];
    }
  }
  geometry.setAttribute("aFrom", new THREE.BufferAttribute(source, 3));
  geometry.setAttribute(
    "aFromColor",
    new THREE.BufferAttribute(sourceColors, 3),
  );
  return geometry;
}
export function terrainValue(x: number, y: number, z: number) {
  return (
    Math.sin(x * 2.3 + Math.cos(z * 3.1)) * Math.cos(y * 2.8 - z) +
    Math.sin(z * 4 + x * 1.3) * 0.32 +
    Math.sin(y * 7 - z * 4) * 0.15
  );
}

src/lib/gameplay.ts:
import { Matrix4 } from "three";
import { GAME_PROGRAM_LIMITS } from "./game-program";
import {
  resolveSceneTransforms,
  transformBounds,
  type WorldBounds,
} from "./scene-transform";
import { carrySupportContact, supportSurfaceHeight } from "./scene-support";
import { entityGeometry } from "./geometry";
import type { Entity, Project } from "./protocol";
import { requireCatalogAsset } from "./asset-catalog";

export type Vec3 = [number, number, number];

export type PlayerState = {
  position: Vec3;
  velocityY: number;
  groundedOn?: string;
  supportPosition?: Vec3;
  supportTop?: number;
  supportMatrix?: number[];
};

export type PlayerInput = {
  x: number;
  z: number;
  jump: boolean;
};

export type GameplayStep = PlayerState & {
  collected: string[];
  contacts: string[];
  /** Events from the selected descending top-surface platform contact. */
  platformContactId?: string;
  bounceContactId?: string;
  won: boolean;
};

function recipeHasCommittedContactBounds(recipe: Entity["geometry"]): boolean {
  if (!recipe) return false;
  if (recipe.kind === "asset")
    return Boolean(requireCatalogAsset(recipe.assetId).bounds);
  if (recipe.kind === "generated") return Boolean(recipe.model?.bounds);
  return true;
}

/**
 * Keep gameplay authority independent of whether a renderer currently owns a
 * decoded asset lease. A ready displayed replacement remains authoritative
 * while a newer recipe is loading; otherwise validated recipe bounds allow a
 * ready first-load or evicted model to keep its contacts and platform support.
 */
export function gameplayEntityForVisualState(
  entity: Entity,
  visualReady: boolean,
  displayed?: Pick<Entity, "geometry" | "stage">,
): Entity {
  const recipe = entity.geometry;
  if (recipe?.kind !== "asset" && recipe?.kind !== "generated") return entity;

  const currentHasBounds = recipeHasCommittedContactBounds(recipe);
  const displayedReady =
    displayed?.stage === "ready" &&
    recipeHasCommittedContactBounds(displayed.geometry);
  if (displayedReady && (!visualReady || !currentHasBounds))
    return {
      ...entity,
      geometry: displayed.geometry,
      stage: displayed.stage,
    };

  if (!currentHasBounds) return { ...entity, stage: "seed" };
  if (visualReady) {
    if (
      displayed?.geometry &&
      recipeHasCommittedContactBounds(displayed.geometry)
    )
      return {
        ...entity,
        geometry: displayed.geometry,
        stage: displayed.stage,
      };
    return entity;
  }
  if (entity.stage === "ready") return entity;
  return { ...entity, stage: "seed" };
}

const GROUND_CENTER_Y = 0.42;
const PLAYER_HALF_HEIGHT = 0.42;
const MOVE_SPEED = 4;
const JUMP_SPEED = 6;
const GRAVITY = 15;
const DEFAULT_PLAYER_START: Vec3 = [0, 0.5, 5];
const FAR_CONTENT_START_THRESHOLD = 32;
const FAR_CONTENT_START_OFFSET = 5;
// Gameplay contact treats the avatar as a small capsule: 0.22 units of
// horizontal reach and its 0.42-unit half-height. Pickups and portals use
// this same geometry-aware tolerance, so an object must touch the avatar in
// 3D rather than merely sharing its ground-plane X/Z position.
const CONTACT_HORIZONTAL_TOLERANCE = 0.22;

export function movingEntityPosition(entity: Entity, time: number): Vec3 {
  const position: Vec3 = [...entity.position];
  if (entity.stage === "ready" && entity.behavior?.type === "move") {
    const axis = entity.behavior.axis ?? "y";
    const index = axis === "x" ? 0 : axis === "y" ? 1 : 2;
    position[index] +=
      Math.sin(time * (entity.behavior.speed ?? 1)) *
      (entity.behavior.amplitude ?? 0.5);
  }
  return position;
}

export function isTextEntryTarget(target: EventTarget | null) {
  return (
    target instanceof Element &&
    Boolean(target.closest("input,textarea,select,[contenteditable]"))
  );
}

function platformTop(
  entity: Entity,
  time: number,
  positionOverride?: Vec3,
  matrix?: Matrix4,
  query?: Vec3,
) {
  const position = positionOverride ?? movingEntityPosition(entity, time);
  const bounds =
    entity.geometry?.kind === "asset"
      ? requireCatalogAsset(entity.geometry.assetId).bounds
      : entity.geometry?.kind === "generated"
        ? entity.geometry.model?.bounds
        : undefined;
  if (matrix && query) {
    const local = bounds
      ? normalizeContactBounds(bounds)
      : {
          min: [-0.55, -0.025, -0.55] as const,
          max: [0.55, 0.52, 0.55] as const,
        };
    const height = supportSurfaceHeight(matrix, local, query[0], query[2]);
    const world = transformBounds(matrix, local);
    return {
      id: entity.id,
      x: (world.min[0] + world.max[0]) / 2,
      z: (world.min[2] + world.max[2]) / 2,
      y: height === undefined ? -Infinity : height + PLAYER_HALF_HEIGHT,
      halfX: (world.max[0] - world.min[0]) / 2,
      halfZ: (world.max[2] - world.min[2]) / 2,
      bounce: entity.behavior?.type === "bounce",
    };
  }
  if (bounds) {
    const { min, max } = bounds;
    const low = min.map((value, i) =>
      Math.min(value * entity.scale[i], max[i] * entity.scale[i]),
    );
    const high = max.map((value, i) =>
      Math.max(value * entity.scale[i], min[i] * entity.scale[i]),
    );
    return {
      id: entity.id,
      x: position[0] + (low[0] + high[0]) / 2,
      z: position[2] + (low[2] + high[2]) / 2,
      y: position[1] + high[1] + PLAYER_HALF_HEIGHT,
      halfX: (high[0] - low[0]) / 2,
      halfZ: (high[2] - low[2]) / 2,
      bounce: entity.behavior?.type === "bounce",
    };
  }
  return {
    id: entity.id,
    x: position[0],
    z: position[2],
    // Reflect both vertical endpoints of the procedural platform mesh.
    y:
      position[1] +
      Math.max(-0.025 * entity.scale[1], 0.52 * entity.scale[1]) +
      PLAYER_HALF_HEIGHT,
    halfX: Math.abs(entity.scale[0]) * 0.55,
    halfZ: Math.abs(entity.scale[2]) * 0.55,
    bounce: entity.behavior?.type === "bounce",
  };
}

function isInsidePlatform(
  platform: ReturnType<typeof platformTop>,
  position: Vec3,
) {
  return (
    Number.isFinite(platform.y) &&
    Math.abs(position[0] - platform.x) <= platform.halfX &&
    Math.abs(position[2] - platform.z) <= platform.halfZ
  );
}

export type ContactBounds = {
  readonly min: readonly [number, number, number];
  readonly max: readonly [number, number, number];
};
export type ContactBoundsInput = {
  readonly min: readonly number[];
  readonly max: readonly number[];
};
const contactBounds = new WeakMap<object, ContactBounds>();

function normalizeContactBounds(bounds: ContactBoundsInput): ContactBounds {
  const min = [...bounds.min];
  const max = [...bounds.max];
  if (
    min.length !== 3 ||
    max.length !== 3 ||
    !min.every(Number.isFinite) ||
    !max.every(Number.isFinite) ||
    min.some((value, index) => value > max[index])
  )
    throw new Error("Contact bounds must be finite, ordered 3D extents.");
  return {
    min: min as [number, number, number],
    max: max as [number, number, number],
  };
}

/**
 * Shared start/reset location for both renderers. Explicit game spawns are
 * player-center positions in world space. Legacy authored games keep their
 * historical start; distant projects without a game program get a start just
 * beyond the positive-Z edge of their ready content.
 */
export function playerSpawnForProject(
  project: Pick<Project, "entities" | "groups" | "game">,
): Vec3 {
  if (project.game)
    return project.game.spawn
      ? [...project.game.spawn]
      : [...DEFAULT_PLAYER_START];

  const readyEntities = project.entities.filter(
    (entity) => entity.stage === "ready",
  );
  if (readyEntities.length === 0) return [...DEFAULT_PLAYER_START];

  const scene = resolveSceneTransforms({
    groups: project.groups,
    entities: project.entities,
  });
  let nearestBounds: WorldBounds | undefined;
  let nearestEntityId: string | undefined;
  let nearestDistanceSquared = Infinity;
  for (const entity of readyEntities) {
    const recipe = entity.geometry;
    let localBounds: ContactBoundsInput | undefined;
    if (recipe?.kind === "asset") {
      localBounds = requireCatalogAsset(recipe.assetId).bounds;
    } else if (recipe?.kind === "generated") {
      localBounds = recipe.model?.bounds;
    } else {
      const geometry = entityGeometry(entity);
      try {
        geometry.computeBoundingBox();
        const box = geometry.boundingBox;
        if (box)
          localBounds = {
            min: box.min.toArray(),
            max: box.max.toArray(),
          };
      } finally {
        geometry.dispose();
      }
    }
    if (!localBounds) return [...DEFAULT_PLAYER_START];

    const resolved = scene.entities.get(entity.id);
    if (!resolved) return [...DEFAULT_PLAYER_START];
    const bounds = transformBounds(
      resolved.worldMatrix,
      normalizeContactBounds(localBounds),
    );
    const dx = Math.max(
      bounds.min[0] - DEFAULT_PLAYER_START[0],
      0,
      DEFAULT_PLAYER_START[0] - bounds.max[0],
    );
    const dz = Math.max(
      bounds.min[2] - DEFAULT_PLAYER_START[2],
      0,
      DEFAULT_PLAYER_START[2] - bounds.max[2],
    );
    const distanceSquared = dx * dx + dz * dz;
    if (distanceSquared <= FAR_CONTENT_START_THRESHOLD ** 2)
      return [...DEFAULT_PLAYER_START];

    if (
      distanceSquared < nearestDistanceSquared ||
      (distanceSquared === nearestDistanceSquared &&
        (!nearestEntityId || entity.id < nearestEntityId))
    ) {
      nearestBounds = bounds;
      nearestEntityId = entity.id;
      nearestDistanceSquared = distanceSquared;
    }
  }

  if (!nearestBounds) return [...DEFAULT_PLAYER_START];
  return [
    (nearestBounds.min[0] + nearestBounds.max[0]) / 2,
    DEFAULT_PLAYER_START[1],
    Math.min(
      GAME_PROGRAM_LIMITS.maxNumericValue,
      nearestBounds.max[2] + FAR_CONTENT_START_OFFSET,
    ),
  ];
}

/** Bind renderer-prepared bounds to one immutable geometry recipe identity. */
export function registerContactBounds(
  recipe: object,
  bounds: ContactBoundsInput,
): ContactBounds {
  if (!recipe || typeof recipe !== "object")
    throw new Error("Contact bounds require an object recipe identity.");
  const normalized = normalizeContactBounds(bounds);
  contactBounds.set(recipe, normalized);
  return normalized;
}

/** Broad-phase contact volumes follow rendered geometry, including multipart bounds. */
export function touchesEntity(
  entity: Entity,
  player: Vec3,
  time: number,
  matrix?: Matrix4,
): boolean {
  const recipe = entity.geometry;
  if (entity.stage !== "ready" || !recipe) return false;
  let bounds = contactBounds.get(recipe);
  if (!bounds) {
    if (recipe.kind === "asset")
      bounds = registerContactBounds(
        recipe,
        requireCatalogAsset(recipe.assetId).bounds,
      );
    else if (recipe.kind === "generated") {
      if (recipe.model?.bounds)
        bounds = registerContactBounds(recipe, recipe.model.bounds);
    } else {
      const geometry = entityGeometry(entity);
      geometry.computeBoundingBox();
      const box = geometry.boundingBox;
      if (box)
        bounds = registerContactBounds(recipe, {
          min: box.min.toArray(),
          max: box.max.toArray(),
        });
      geometry.dispose();
    }
    if (!bounds) return false;
    contactBounds.set(recipe, bounds);
  }
  const worldBounds = matrix ? transformBounds(matrix, bounds) : undefined;
  const origin = movingEntityPosition(entity, time);
  return [0, 1, 2].every((axis) => {
    const low =
      worldBounds?.min[axis] ??
      origin[axis] +
        Math.min(
          bounds!.min[axis] * entity.scale[axis],
          bounds!.max[axis] * entity.scale[axis],
        );
    const high =
      worldBounds?.max[axis] ??
      origin[axis] +
        Math.max(
          bounds!.min[axis] * entity.scale[axis],
          bounds!.max[axis] * entity.scale[axis],
        );
    const radius =
      (axis === 1 ? PLAYER_HALF_HEIGHT : CONTACT_HORIZONTAL_TOLERANCE) + 1e-5;
    return player[axis] + radius >= low && player[axis] - radius <= high;
  });
}

export function stepGameplay(
  state: PlayerState,
  input: PlayerInput,
  entities: Entity[],
  collectedBefore: readonly string[],
  time: number,
  delta: number,
  collisionTargets?: ReadonlySet<string>,
  worldMatrices?: ReadonlyMap<string, Matrix4>,
): GameplayStep {
  const dt = Math.min(Math.max(delta, 0), 0.04);
  const position: Vec3 = [...state.position];
  const readyPlatforms = entities.filter(
    (entity) =>
      entity.stage === "ready" &&
      (entity.geometry?.kind === "platform" ||
        (entity.geometry?.kind === "generated" &&
          entity.geometry.collision === "platform" &&
          !!entity.geometry.model) ||
        (entity.geometry?.kind === "asset" &&
          requireCatalogAsset(entity.geometry.assetId).tags.some(
            (tag) => tag === "platform" || tag === "bridge",
          ))),
  );

  // A grounded player inherits the exact displacement of a moving platform.
  // This also makes compatible speed/amplitude edits reconcile without a reset.
  const support = state.groundedOn
    ? readyPlatforms.find((entity) => entity.id === state.groundedOn)
    : undefined;
  const supportPose = support ? worldMatrices?.get(support.id) : undefined;
  const previousSupportPose =
    supportPose && state.supportMatrix?.length === 16
      ? new Matrix4().fromArray(state.supportMatrix)
      : supportPose;
  const beforePosition = support
    ? (state.supportPosition ?? movingEntityPosition(support, time - dt))
    : undefined;
  const supportedBeforeDisplacement = Boolean(
    support &&
    beforePosition &&
    isInsidePlatform(
      platformTop(support, time, beforePosition, previousSupportPose, position),
      position,
    ),
  );
  if (support && beforePosition && supportedBeforeDisplacement) {
    const contact: Vec3 = [
      position[0],
      position[1] - PLAYER_HALF_HEIGHT,
      position[2],
    ];
    const carried =
      supportPose && previousSupportPose
        ? carrySupportContact(previousSupportPose, supportPose, contact)
        : undefined;
    if (carried) {
      position[0] = carried[0];
      position[1] = carried[1] + PLAYER_HALF_HEIGHT;
      position[2] = carried[2];
    } else if (!supportPose) {
      const before = beforePosition;
      const after = movingEntityPosition(support, time);
      position[0] += after[0] - before[0];
      const afterTop = platformTop(support, time).y;
      const beforeTop =
        state.supportTop ?? platformTop(support, time, before).y;
      position[1] += afterTop - beforeTop;
      position[2] += after[2] - before[2];
    }
  }

  const magnitude = Math.hypot(input.x, input.z);
  if (magnitude) {
    position[0] += (input.x / magnitude) * MOVE_SPEED * dt;
    position[2] += (input.z / magnitude) * MOVE_SPEED * dt;
  }

  let velocityY = state.velocityY;
  const supportedAfterDisplacement = Boolean(
    support &&
    supportedBeforeDisplacement &&
    isInsidePlatform(
      platformTop(support, time, undefined, supportPose, position),
      position,
    ),
  );
  let groundedOn = supportedAfterDisplacement ? support?.id : undefined;
  let supportPosition = supportedAfterDisplacement
    ? state.supportPosition
    : undefined;
  let supportTop = supportedAfterDisplacement ? state.supportTop : undefined;
  const wasSupported =
    supportedAfterDisplacement || position[1] <= GROUND_CENTER_Y + 0.04;
  if (input.jump && wasSupported) {
    velocityY = JUMP_SPEED;
    groundedOn = undefined;
    supportPosition = undefined;
    supportTop = undefined;
  }
  velocityY -= GRAVITY * dt;
  if (supportedAfterDisplacement && supportPose && support && !input.jump)
    position[1] = platformTop(
      support,
      time,
      undefined,
      supportPose,
      position,
    ).y;
  const previousY = position[1];
  position[1] += velocityY * dt;

  let floor = GROUND_CENTER_Y;
  let floorId: string | undefined;
  let bounce = false;
  for (const entity of readyPlatforms) {
    const platform = platformTop(
      entity,
      time,
      undefined,
      worldMatrices?.get(entity.id),
      position,
    );
    const inside = isInsidePlatform(platform, position);
    // Only land while descending and crossing a top surface. This avoids
    // teleporting onto a platform when walking below or beside it.
    if (
      inside &&
      velocityY <= 0 &&
      previousY >= platform.y - 0.08 &&
      position[1] <= platform.y &&
      platform.y >= floor
    ) {
      floor = platform.y;
      floorId = platform.id;
      bounce = platform.bounce;
    }
  }
  if (position[1] <= floor) {
    position[1] = floor;
    velocityY = bounce ? JUMP_SPEED * 1.18 : 0;
    groundedOn = bounce ? undefined : floorId;
    supportPosition = floorId
      ? movingEntityPosition(
          readyPlatforms.find((entity) => entity.id === floorId)!,
          time,
        )
      : undefined;
    supportTop = floorId ? floor : undefined;
  } else if (!floorId) {
    groundedOn = undefined;
    supportPosition = undefined;
    supportTop = undefined;
  }

  const collected = [...collectedBefore];
  for (const entity of entities) {
    if (
      entity.behavior?.type === "collect" &&
      touchesEntity(entity, position, time, worldMatrices?.get(entity.id)) &&
      !collected.includes(entity.id)
    )
      collected.push(entity.id);
  }
  const collectibleIds = entities
    .filter(
      (entity) =>
        entity.stage === "ready" && entity.behavior?.type === "collect",
    )
    .map((entity) => entity.id);
  const won = entities.some((entity) => {
    if (entity.stage !== "ready" || entity.behavior?.type !== "portal")
      return false;
    return (
      collectibleIds.every((id) => collected.includes(id)) &&
      touchesEntity(entity, position, time, worldMatrices?.get(entity.id))
    );
  });
  return {
    position,
    velocityY,
    groundedOn,
    supportPosition,
    supportTop,
    supportMatrix: groundedOn
      ? worldMatrices?.get(groundedOn)?.toArray()
      : undefined,
    collected,
    contacts: entities
      .filter(
        (entity) =>
          (collisionTargets === undefined || collisionTargets.has(entity.id)) &&
          !collectedBefore.includes(entity.id) &&
          touchesEntity(entity, position, time, worldMatrices?.get(entity.id)),
      )
      .map((entity) => entity.id),
    ...(floorId ? { platformContactId: floorId } : {}),
    ...(floorId && bounce ? { bounceContactId: floorId } : {}),
    won,
  };
}

