import type { Project } from "./protocol";
import type { SceneReviewImage } from "./review-image";
import type { SceneReviewPhase } from "./scene-review";
import type { SceneReviewStructuralObservations } from "./server/scene-review-observations";
import { validatedClientRunId } from "./generation-observability";
import {
  isGenerationReady,
  type GenerationConnection,
} from "./generation-connection";

export type AuthoringReviewRequest = {
  runId: string;
  phase: SceneReviewPhase;
  prompt: string;
  project: Project;
  selected?: string;
  browserModeling: boolean;
  reviewImage?: SceneReviewImage;
  structuralObservations?: SceneReviewStructuralObservations;
  feedback?: string;
};

/** Build a review request from the original connection, never from model output. */
export function authoringReviewRequest(
  connection: GenerationConnection,
  input: AuthoringReviewRequest,
  clientRunId: string,
): { url: string; init: RequestInit } {
  if (
    !["free", "openrouter", "gateway", "chatgpt-hosted"].includes(
      connection.provider,
    ) ||
    !isGenerationReady(connection)
  )
    throw Error("Choose a complete AI connection.");
  if (!validatedClientRunId(input.runId))
    throw Error("The authoring review run is unavailable.");
  const validatedClientId = validatedClientRunId(clientRunId);
  if (!validatedClientId) throw Error("The authoring request is unavailable.");
  const hosted = connection.provider === "chatgpt-hosted";
  const body = {
    runId: input.runId,
    phase: input.phase,
    prompt: input.prompt,
    project: input.project,
    ...(input.selected ? { selected: input.selected } : {}),
    browserModeling: input.browserModeling,
    localModeling: false,
    ...(input.reviewImage ? { reviewImage: input.reviewImage } : {}),
    ...(input.structuralObservations
      ? { structuralObservations: input.structuralObservations }
      : {}),
    ...(input.feedback ? { feedback: input.feedback } : {}),
    ...(hosted
      ? { model: connection.model, effort: connection.effort }
      : connection.provider === "free"
        ? { provider: "free" }
        : {
            provider: connection.provider,
            model: connection.model,
            key: connection.key,
          }),
  };
  return {
    url: hosted ? "/api/chatgpt/review" : "/api/generate/review",
    init: {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Orbsie-Client-Run-Id": validatedClientId,
      },
      body: JSON.stringify(body),
      credentials: "same-origin",
      redirect: "error",
      cache: "no-store",
    },
  };
}

src/lib/scene-review.ts:
import { z } from "zod";
import { modelCommandSchemaForCapabilities } from "./protocol";

export type SceneReviewPhase = "review" | "final-review";
export type SceneReviewScope = "visual+structural" | "structural-only";

const identifier = z
  .string()
  .min(1)
  .max(80)
  .regex(/^[\w-]+$/);
const issueSchema = z
  .object({
    summary: z.string().trim().min(1).max(300),
    entityIds: z.array(identifier).max(16),
  })
  .strict();

/** Model output shape. A parsed result still needs scene/asset-policy validation. */
export function sceneReviewResultSchema(browserModeling: boolean) {
  return z
    .object({
      version: z.literal(1),
      projectId: identifier,
      reviewedRevision: z
        .number()
        .int()
        .nonnegative()
        .max(Number.MAX_SAFE_INTEGER),
      scope: z.enum(["visual+structural", "structural-only"]),
      verdict: z.enum(["accept", "revise"]),
      summary: z.string().trim().min(1).max(600),
      issues: z.array(issueSchema).max(8),
      corrections: z
        .array(modelCommandSchemaForCapabilities(false, browserModeling))
        .max(16),
    })
    .strict()
    .superRefine((result, context) => {
      if (
        result.verdict === "accept" &&
        (result.issues.length || result.corrections.length)
      )
        context.addIssue({
          code: "custom",
          path: ["verdict"],
          message:
            "Acceptance cannot include unresolved defects or corrections.",
        });
      if (result.verdict === "revise" && !result.issues.length)
        context.addIssue({
          code: "custom",
          path: ["issues"],
          message: "A revision verdict must identify a concrete defect.",
        });
      if (
        result.corrections.some((command) => command.type === "commit_revision")
      )
        context.addIssue({
          code: "custom",
          path: ["corrections"],
          message: "The review lifecycle owns the correction commit.",
        });
    });
}

export type SceneReviewResult = z.infer<
  ReturnType<typeof sceneReviewResultSchema>
>;

/**
 * Bind the verdict to the caller's admitted phase and actual evidence scope.
 * This does not authorize a model call or apply corrections: callers must first
 * admit the server ledger phase, then validate corrections against its bound scene.
 */
export function parseSceneReviewResult(
  raw: unknown,
  expected: {
    projectId: string;
    revision: number;
    scope: SceneReviewScope;
    phase: SceneReviewPhase;
    browserModeling: boolean;
    entityIds: readonly string[];
  },
): SceneReviewResult {
  const result = sceneReviewResultSchema(expected.browserModeling).parse(raw);
  if (
    result.projectId !== expected.projectId ||
    result.reviewedRevision !== expected.revision
  )
    throw Error("This review belongs to another world or revision.");
  if (result.scope !== expected.scope)
    throw Error("The review scope does not match the supplied evidence.");
  if (expected.phase === "final-review" && result.corrections.length)
    throw Error("The final review cannot apply more corrections.");
  if (
    expected.phase === "review" &&
    result.verdict === "revise" &&
    !result.corrections.length
  )
    throw Error("The first review must provide a correction for its defect.");
  const entities = new Set(expected.entityIds);
  if (
    result.issues.some((issue) =>
      issue.entityIds.some((id) => !entities.has(id)),
    )
  )
    throw Error(
      "A review issue refers to an object outside the reviewed scene.",
    );
  return result;
}

src/lib/authoring-review-response.ts:
import { z } from "zod";
import {
  modelCommandSchemaForCapabilities,
  type ModelCommand,
} from "./protocol";
import {
  parseSceneReviewResult,
  type SceneReviewPhase,
  type SceneReviewScope,
} from "./scene-review";

export type AuthoringReviewResponseExpectation = {
  projectId: string;
  revision: number;
  phase: SceneReviewPhase;
  scope: SceneReviewScope;
  browserModeling: boolean;
  entityIds: readonly string[];
};

/** Parse a public review reply before applying any server-approved command. */
export function parseAuthoringReviewResponse(
  raw: unknown,
  expected: AuthoringReviewResponseExpectation,
) {
  const bindingSchema = z
    .object({
      revision: z.number().int().nonnegative().max(Number.MAX_SAFE_INTEGER),
      digest: z.string().regex(/^[a-f0-9]{64}$/),
    })
    .strict();
  const parsed = z
    .object({
      review: z.unknown(),
      corrections: z
        .array(
          modelCommandSchemaForCapabilities(false, expected.browserModeling),
        )
        .max(17),
      binding: bindingSchema,
      revision: bindingSchema.shape.revision,
      digest: bindingSchema.shape.digest,
      scope: z.enum(["visual+structural", "structural-only"]),
      remainingCalls: z.number().int().min(0).max(1),
    })
    .strict()
    .parse(raw);
  const review = parseSceneReviewResult(parsed.review, expected);
  if (
    parsed.revision !== parsed.binding.revision ||
    parsed.digest !== parsed.binding.digest ||
    parsed.scope !== review.scope
  )
    throw Error("The scene review reply is inconsistent.");
  const revising = expected.phase === "review" && review.verdict === "revise";
  const corrections = parsed.corrections as unknown as readonly ModelCommand[];
  if (revising) {
    if (
      parsed.remainingCalls !== 1 ||
      corrections.length !== review.corrections.length + 1 ||
      corrections.at(-1)?.type !== "commit_revision" ||
      corrections
        .slice(0, -1)
        .some((command) => command.type === "commit_revision") ||
      parsed.binding.revision !== expected.revision + corrections.length
    )
      throw Error("The scene review correction batch is inconsistent.");
  } else if (
    parsed.remainingCalls !== 0 ||
    corrections.length !== 0 ||
    parsed.binding.revision !== expected.revision
  )
    throw Error("The scene review verdict is inconsistent.");
  return {
    review,
    corrections,
    binding: parsed.binding,
    scope: parsed.scope,
    remainingCalls: parsed.remainingCalls,
  };
}

src/lib/review-image.ts:
/**
 * A renderer capture that may be sent to a trusted model adapter for review.
 * This type intentionally contains only primitive, bounded data. Callers must
 * bind projectId and revision to the current server-owned project before
 * constructing a model request.
 */
export type SceneReviewRenderer = "webgl" | "software";

export type SceneReviewImage = {
  projectId: string;
  revision: number;
  renderer: SceneReviewRenderer;
  width: number;
  height: number;
  image: string;
};

export const MAX_REVIEW_IMAGE_BYTES = 128 * 1024;
export const MAX_REVIEW_IMAGE_PIXELS = 2_000_000;
const MAX_REVIEW_IMAGE_DECODED_BYTES = Math.floor(
  (MAX_REVIEW_IMAGE_BYTES * 3) / 4,
);
const DATA_URL_PREFIX = "data:image/png;base64,";
const PNG_SIGNATURE = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];
const IMAGE_KEYS = [
  "projectId",
  "revision",
  "renderer",
  "width",
  "height",
  "image",
];

export type ReviewImageErrorCode =
  | "invalid-image"
  | "invalid-capture"
  | "identity-mismatch"
  | "dimension-mismatch"
  | "payload-too-large";

/** Safe, typed failures for the internal image transport boundary. */
export class ReviewImageValidationError extends Error {
  readonly code: ReviewImageErrorCode;

  constructor(code: ReviewImageErrorCode, message: string) {
    super(message);
    this.name = "ReviewImageValidationError";
    this.code = code;
  }
}

export class UnsupportedReviewImageError extends Error {
  readonly code = "unsupported-image" as const;

  constructor() {
    super("The selected model does not support image review.");
    this.name = "UnsupportedReviewImageError";
  }
}

function invalid(code: ReviewImageErrorCode, message: string): never {
  throw new ReviewImageValidationError(code, message);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

function utf8Bytes(value: string): number {
  return new TextEncoder().encode(value).byteLength;
}

function validProjectId(value: unknown): value is string {
  return (
    typeof value === "string" &&
    value.length > 0 &&
    value.length <= 80 &&
    value.trim() === value &&
    !/[\u0000-\u001f\u007f]/.test(value)
  );
}

function validRevision(value: unknown): value is number {
  return Number.isSafeInteger(value) && (value as number) >= 0;
}

function validDimension(value: unknown): value is number {
  return Number.isSafeInteger(value) && (value as number) > 0;
}

function hasExactKeys(value: Record<string, unknown>, keys: readonly string[]) {
  return (
    Object.keys(value).length === keys.length &&
    Object.keys(value).every((key) => keys.includes(key))
  );
}

function decodeBase64(payload: string): Uint8Array {
  // Check the textual form before atob. This rejects whitespace and non-
  // canonical padding without asking the decoder to allocate untrusted data.
  if (
    payload.length === 0 ||
    payload.length % 4 !== 0 ||
    !/^[A-Za-z0-9+/]+={0,2}$/.test(payload)
  )
    invalid("invalid-image", "Review image data is not valid PNG data.");
  let binary: string;
  try {
    binary = globalThis.atob(payload);
  } catch {
    invalid("invalid-image", "Review image data is not valid PNG data.");
  }
  if (binary.length === 0 || binary.length > MAX_REVIEW_IMAGE_DECODED_BYTES)
    invalid("payload-too-large", "Review image exceeds the image limit.");
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index++)
    bytes[index] = binary.charCodeAt(index);
  return bytes;
}

function inspectPngDataUrl(image: unknown): {
  width: number;
  height: number;
  byteLength: number;
} {
  if (typeof image !== "string")
    invalid("invalid-image", "Review image must be a PNG data URL.");
  if (image.length > MAX_REVIEW_IMAGE_BYTES)
    invalid("payload-too-large", "Review image exceeds the image limit.");
  if (utf8Bytes(image) > MAX_REVIEW_IMAGE_BYTES)
    invalid("payload-too-large", "Review image exceeds the image limit.");
  if (!image.startsWith(DATA_URL_PREFIX))
    invalid("invalid-image", "Review image must be a PNG data URL.");
  const bytes = decodeBase64(image.slice(DATA_URL_PREFIX.length));
  if (bytes.byteLength < 33)
    invalid("invalid-image", "Review image is not a complete PNG.");
  for (let index = 0; index < PNG_SIGNATURE.length; index++)
    if (bytes[index] !== PNG_SIGNATURE[index])
      invalid("invalid-image", "Review image is not a PNG image.");

  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  // PNG's first chunk must be the complete 13-byte IHDR chunk. Reading only
  // these bounded bytes is enough to validate dimensions without parsing the
  // rest of the image or accepting a non-PNG data URL.
  if (
    view.getUint32(8) !== 13 ||
    String.fromCharCode(bytes[12], bytes[13], bytes[14], bytes[15]) !== "IHDR"
  )
    invalid("invalid-image", "Review image has an invalid PNG header.");
  const width = view.getUint32(16);
  const height = view.getUint32(20);
  if (width < 1 || height < 1 || width > MAX_REVIEW_IMAGE_PIXELS / height)
    invalid("invalid-image", "Review image exceeds the pixel limit.");

  const bitDepth = bytes[24];
  const colorType = bytes[25];
  const allowedBitDepths: Record<number, readonly number[]> = {
    0: [1, 2, 4, 8, 16],
    2: [8, 16],
    3: [1, 2, 4, 8],
    4: [8, 16],
    6: [8, 16],
  };
  if (
    !Object.hasOwn(allowedBitDepths, colorType) ||
    !allowedBitDepths[colorType].includes(bitDepth) ||
    bytes[26] !== 0 ||
    bytes[27] !== 0 ||
    (bytes[28] !== 0 && bytes[28] !== 1)
  )
    invalid("invalid-image", "Review image has an invalid PNG format.");

  let offset = 8;
  let sawImageData = false;
  let sawEnd = false;
  let chunkCount = 0;
  while (offset < bytes.byteLength) {
    if (++chunkCount > 4096 || bytes.byteLength - offset < 12)
      invalid("invalid-image", "Review image has an invalid PNG structure.");
    const length = view.getUint32(offset);
    const chunkEnd = offset + 12 + length;
    if (!Number.isSafeInteger(chunkEnd) || chunkEnd > bytes.byteLength)
      invalid("invalid-image", "Review image has an invalid PNG structure.");
    const type = String.fromCharCode(
      bytes[offset + 4],
      bytes[offset + 5],
      bytes[offset + 6],
      bytes[offset + 7],
    );
    if (offset === 8 && (type !== "IHDR" || length !== 13))
      invalid("invalid-image", "Review image has an invalid PNG header.");
    if (type === "IDAT") sawImageData = true;
    if (type === "IEND") {
      if (
        length !== 0 ||
        sawEnd ||
        !sawImageData ||
        chunkEnd !== bytes.byteLength
      )
        invalid("invalid-image", "Review image has an invalid PNG structure.");
      sawEnd = true;
      break;
    }
    offset = chunkEnd;
  }
  if (!sawEnd)
    invalid("invalid-image", "Review image has an incomplete PNG structure.");
  return { width, height, byteLength: utf8Bytes(image) };
}

/** Validate a PNG data URL independently of any renderer/client metadata. */
export function validateReviewImageDataUrl(value: unknown) {
  return inspectPngDataUrl(value);
}

/**
 * Validate one complete capture and optionally bind it to a server-owned
 * project snapshot. The returned value is a fresh primitive copy.
 */
export function validateSceneReviewImage(
  value: unknown,
  expected?: { projectId: string; revision: number },
): SceneReviewImage {
  if (!isRecord(value) || !hasExactKeys(value, IMAGE_KEYS))
    invalid("invalid-capture", "Review image metadata is invalid.");
  if (
    !validProjectId(value.projectId) ||
    !validRevision(value.revision) ||
    (value.renderer !== "webgl" && value.renderer !== "software") ||
    !validDimension(value.width) ||
    !validDimension(value.height) ||
    typeof value.image !== "string"
  )
    invalid("invalid-capture", "Review image metadata is invalid.");
  if (expected) {
    if (value.projectId !== expected.projectId)
      invalid("identity-mismatch", "Review image belongs to another project.");
    if (value.revision !== expected.revision)
      invalid("identity-mismatch", "Review image belongs to another revision.");
  }
  const png = inspectPngDataUrl(value.image);
  if (png.width !== value.width || png.height !== value.height)
    invalid(
      "dimension-mismatch",
      "Review image dimensions do not match metadata.",
    );
  return {
    projectId: value.projectId,
    revision: value.revision,
    renderer: value.renderer,
    width: value.width,
    height: value.height,
    image: value.image,
  };
}

src/lib/scene-review-capture.ts:
"use client";

import {
  MAX_REVIEW_IMAGE_BYTES,
  validateReviewImageDataUrl,
  type SceneReviewRenderer,
} from "./review-image";

export type { SceneReviewRenderer } from "./review-image";

export type SceneReviewSourceState = {
  renderer: SceneReviewRenderer;
  projectId: string;
  revision: number;
  /** Revision whose current geometry has actually reached the renderer. */
  renderedRevision: number;
  transitionSettled: boolean;
  mounted: boolean;
  readyAssetIds: readonly string[];
  pendingAssetIds: readonly string[];
  failedAssetIds: readonly string[];
  errors: readonly string[];
};

export type SceneReviewCaptureSource = {
  renderer: SceneReviewRenderer;
  getState: () => SceneReviewSourceState;
  /** Returns a PNG data URL containing the game canvas only. */
  capture: () => string;
};

export type SceneReviewCaptureRequest = {
  projectId: string;
  revision: number;
  renderer?: SceneReviewRenderer;
  timeoutMs?: number;
  signal?: AbortSignal;
};

export type SceneReviewCaptureResult = {
  image: string;
  width: number;
  height: number;
  byteLength: number;
  renderer: SceneReviewRenderer;
  projectId: string;
  revision: number;
  readiness: {
    renderedRevision: number;
    transitionSettled: boolean;
    readyAssetIds: string[];
    pendingAssetIds: string[];
    failedAssetIds: string[];
  };
  errors: string[];
};

export type SceneReviewCaptureErrorCode =
  | "aborted"
  | "timeout"
  | "unavailable"
  | "project-mismatch"
  | "superseded-revision"
  | "asset-failed"
  | "invalid-image";

export class SceneReviewCaptureError extends Error {
  readonly code: SceneReviewCaptureErrorCode;
  readonly details?: Record<string, unknown>;

  constructor(
    code: SceneReviewCaptureErrorCode,
    message: string,
    details?: Record<string, unknown>,
  ) {
    super(message);
    this.name = "SceneReviewCaptureError";
    this.code = code;
    this.details = details;
  }
}

const DEFAULT_TIMEOUT_MS = 5000;
const MAX_TIMEOUT_MS = 10000;
// Leave room for this data URL in the existing bounded review request. The
// cap is on the encoded payload callers actually transport, with a matching
// decoded cap for the PNG parser.
const CAPTURE_EDGES = [512, 384, 256, 192, 128] as const;

function captureError(
  code: SceneReviewCaptureErrorCode,
  message: string,
  details?: Record<string, unknown>,
): SceneReviewCaptureError {
  return new SceneReviewCaptureError(code, message, details);
}

function assertNotAborted(signal: AbortSignal | undefined): void {
  if (signal?.aborted)
    throw captureError("aborted", "Scene review capture was cancelled.");
}

function inspectPng(image: string): {
  width: number;
  height: number;
  byteLength: number;
} {
  try {
    return validateReviewImageDataUrl(image);
  } catch (error) {
    throw captureError(
      "invalid-image",
      error instanceof Error
        ? error.message
        : "Scene review capture is not valid PNG data.",
      error instanceof Error && "code" in error
        ? { reason: (error as { code?: unknown }).code }
        : undefined,
    );
  }
}

/** Copy one renderer canvas into a bounded, aspect-preserving review image. */
export function captureSceneCanvas(canvas: HTMLCanvasElement): string {
  if (!canvas.width || !canvas.height)
    throw new Error("Scene canvas is not ready.");
  let lastImage = "";
  for (const maxEdge of CAPTURE_EDGES) {
    const scale = Math.min(1, maxEdge / Math.max(canvas.width, canvas.height));
    const width = Math.max(1, Math.round(canvas.width * scale));
    const height = Math.max(1, Math.round(canvas.height * scale));
    const output = document.createElement("canvas");
    output.width = width;
    output.height = height;
    const context = output.getContext("2d");
    if (!context) throw new Error("Could not capture the game canvas.");
    context.fillStyle = "#07100f";
    context.fillRect(0, 0, width, height);
    context.drawImage(canvas, 0, 0, width, height);
    lastImage = output.toDataURL("image/png");
    if (
      new TextEncoder().encode(lastImage).byteLength <= MAX_REVIEW_IMAGE_BYTES
    )
      return lastImage;
  }
  throw new Error("Scene review capture exceeds the image limit.");
}

function waitForChange(
  listeners: Set<() => void>,
  timeoutMs: number,
  signal: AbortSignal | undefined,
): Promise<void> {
  return new Promise((resolve, reject) => {
    let timer: ReturnType<typeof setTimeout> | undefined;
    const cleanup = () => {
      if (timer !== undefined) clearTimeout(timer);
      listeners.delete(onChange);
      signal?.removeEventListener("abort", onAbort);
    };
    const finish = () => {
      cleanup();
      resolve();
    };
    const onChange = () => finish();
    const onAbort = () => {
      cleanup();
      reject(captureError("aborted", "Scene review capture was cancelled."));
    };
    listeners.add(onChange);
    signal?.addEventListener("abort", onAbort, { once: true });
    if (signal?.aborted) {
      onAbort();
      return;
    }
    timer = setTimeout(finish, Math.max(1, timeoutMs));
  });
}

function copyState(state: SceneReviewSourceState): SceneReviewSourceState {
  return {
    ...state,
    readyAssetIds: [...state.readyAssetIds],
    pendingAssetIds: [...state.pendingAssetIds],
    failedAssetIds: [...state.failedAssetIds],
    errors: [...state.errors],
  };
}

/**
 * A small process-local registry keeps renderer readiness out of React state.
 * Renderers register refs and notify only when a resource/transition changes;
 * captures can then wait without exposing scene objects or mutators.
 */
export class SceneReviewCaptureBridge {
  private readonly sources = new Map<symbol, SceneReviewCaptureSource>();
  private readonly listeners = new Set<() => void>();

  register(source: SceneReviewCaptureSource): () => void {
    const token = Symbol("scene-review-source");
    this.sources.set(token, source);
    this.notify();
    return () => {
      if (this.sources.delete(token)) this.notify();
    };
  }

  notify(): void {
    for (const listener of [...this.listeners]) listener();
  }

  async capture(
    request: SceneReviewCaptureRequest,
  ): Promise<SceneReviewCaptureResult> {
    const timeoutMs = Math.min(
      MAX_TIMEOUT_MS,
      Math.max(1, request.timeoutMs ?? DEFAULT_TIMEOUT_MS),
    );
    const deadline = Date.now() + timeoutMs;
    let sawSource = false;
    let lastState: SceneReviewSourceState | undefined;
    while (Date.now() < deadline) {
      assertNotAborted(request.signal);
      const candidates = [...this.sources.values()].filter(
        (source) => !request.renderer || source.renderer === request.renderer,
      );
      let matching:
        | { source: SceneReviewCaptureSource; state: SceneReviewSourceState }
        | undefined;
      for (const source of candidates) {
        const state = copyState(source.getState());
        sawSource = true;
        lastState = state;
        if (!state.mounted) continue;
        if (state.projectId !== request.projectId) continue;
        if (
          state.revision > request.revision ||
          state.renderedRevision > request.revision
        )
          throw captureError(
            "superseded-revision",
            "The requested scene revision has been replaced.",
            {
              expectedRevision: request.revision,
              actualRevision: state.revision,
            },
          );
        matching = { source, state };
        break;
      }
      if (!matching) {
        if (
          candidates.length > 0 &&
          candidates.every((source) => !source.getState().mounted)
        )
          throw captureError(
            "unavailable",
            "The scene renderer was unmounted before capture completed.",
          );
        const otherProject = candidates.find((source) => {
          const state = source.getState();
          return state.mounted && state.projectId !== request.projectId;
        });
        if (otherProject)
          throw captureError(
            "project-mismatch",
            "The requested scene project is no longer mounted.",
            { expectedProjectId: request.projectId },
          );
        await waitForChange(
          this.listeners,
          Math.min(50, deadline - Date.now()),
          request.signal,
        );
        continue;
      }
      const { source, state } = matching;
      if (state.failedAssetIds.length) {
        throw captureError(
          "asset-failed",
          "A scene asset failed before review capture.",
          { failedAssetIds: state.failedAssetIds },
        );
      }
      if (
        state.revision !== request.revision ||
        state.renderedRevision !== request.revision ||
        state.pendingAssetIds.length ||
        !state.transitionSettled
      ) {
        await waitForChange(
          this.listeners,
          Math.min(50, deadline - Date.now()),
          request.signal,
        );
        continue;
      }
      assertNotAborted(request.signal);
      let image: string;
      try {
        image = source.capture();
      } catch (error) {
        throw captureError(
          "invalid-image",
          "Scene renderer could not produce a capture.",
          {
            reason: error instanceof Error ? error.message : String(error),
          },
        );
      }
      const dimensions = inspectPng(image);
      assertNotAborted(request.signal);
      const after = copyState(source.getState());
      if (
        !after.mounted ||
        after.projectId !== request.projectId ||
        after.revision !== request.revision ||
        after.renderedRevision !== request.revision ||
        after.pendingAssetIds.length ||
        after.failedAssetIds.length ||
        !after.transitionSettled
      ) {
        lastState = after;
        await waitForChange(
          this.listeners,
          Math.min(50, deadline - Date.now()),
          request.signal,
        );
        continue;
      }
      return {
        image,
        ...dimensions,
        renderer: after.renderer,
        projectId: after.projectId,
        revision: after.revision,
        readiness: {
          renderedRevision: after.renderedRevision,
          transitionSettled: after.transitionSettled,
          readyAssetIds: [...after.readyAssetIds],
          pendingAssetIds: [...after.pendingAssetIds],
          failedAssetIds: [...after.failedAssetIds],
        },
        errors: [...after.errors],
      };
    }
    assertNotAborted(request.signal);
    throw captureError(
      sawSource ? "timeout" : "unavailable",
      sawSource
        ? "Scene review capture did not reach a stable ready revision in time."
        : "No scene renderer is mounted for review capture.",
      lastState
        ? {
            projectId: lastState.projectId,
            revision: lastState.revision,
            renderedRevision: lastState.renderedRevision,
            pendingAssetIds: lastState.pendingAssetIds,
          }
        : undefined,
    );
  }
}

export const sceneReviewCaptureBridge = new SceneReviewCaptureBridge();

export function registerSceneReviewCaptureSource(
  source: SceneReviewCaptureSource,
): () => void {
  return sceneReviewCaptureBridge.register(source);
}

export function notifySceneReviewCaptureChanged(): void {
  sceneReviewCaptureBridge.notify();
}

export function captureSceneReview(
  request: SceneReviewCaptureRequest,
): Promise<SceneReviewCaptureResult> {
  return sceneReviewCaptureBridge.capture(request);
}

