import type { Entity } from "./protocol";
import {
  selectFormationResidents,
  type FormationResidencySelection,
} from "./formation-residency";
import type { WorldNavigationVec3 } from "./world-navigation";
import type { WorldNavigationBounds } from "./world-navigation";

export type FormationProxyVisualBounds = Readonly<{
  center: WorldNavigationVec3;
  size: WorldNavigationVec3;
}>;

export type FormationProxyResolvedNode = Readonly<{
  worldMatrix: Readonly<{ elements: readonly number[] }>;
  worldPosition: WorldNavigationVec3;
}>;

export type FormationProxyReviewSnapshot = Readonly<{
  ready: boolean;
  pending: boolean;
  failed: false;
  renderedRevision: number;
}>;

/** Offscreen completed proxies need no draw; visible ones wait for this revision. */
export function formationProxyReviewSnapshot(
  currentRevision: number,
  drawnRevision: number | undefined,
  visible: boolean,
): FormationProxyReviewSnapshot {
  const ready = !visible || drawnRevision === currentRevision;
  return {
    ready,
    pending: !ready,
    failed: false,
    renderedRevision: ready ? currentRevision : (drawnRevision ?? -1),
  };
}

/**
 * Place a proxy from resolved world-space AABB data. If geometry bounds are
 * unavailable, conservatively bound a unit proxy by the resolved affine
 * transform's axis extents, including rotation, scale, and shear.
 */
export function formationProxyVisualBounds(
  bounds: WorldNavigationBounds | undefined,
  sceneNode: FormationProxyResolvedNode | undefined,
): FormationProxyVisualBounds | undefined {
  if (
    bounds &&
    Array.isArray(bounds.min) &&
    bounds.min.length === 3 &&
    Array.isArray(bounds.max) &&
    bounds.max.length === 3 &&
    bounds.min.every(Number.isFinite) &&
    bounds.max.every(Number.isFinite) &&
    bounds.min.every((value, axis) => value <= bounds.max[axis])
  ) {
    const size = bounds.min.map((value, axis) =>
      Math.max(0.12, bounds.max[axis] - value),
    ) as unknown as WorldNavigationVec3;
    const center = bounds.min.map(
      (value, axis) => value + (bounds.max[axis] - value) / 2,
    ) as unknown as WorldNavigationVec3;
    if ([...center, ...size].every(Number.isFinite)) return { center, size };
  }

  const matrix = sceneNode?.worldMatrix.elements;
  const center = sceneNode?.worldPosition;
  if (
    !matrix ||
    matrix.length < 16 ||
    !matrix.every(Number.isFinite) ||
    !Array.isArray(center) ||
    center.length !== 3 ||
    !center.every(Number.isFinite)
  )
    return undefined;
  const size: WorldNavigationVec3 = [
    2 *
      Math.max(
        0.75,
        Math.abs(matrix[0]) + Math.abs(matrix[4]) + Math.abs(matrix[8]),
      ),
    2 *
      Math.max(
        0.75,
        Math.abs(matrix[1]) + Math.abs(matrix[5]) + Math.abs(matrix[9]),
      ),
    2 *
      Math.max(
        0.75,
        Math.abs(matrix[2]) + Math.abs(matrix[6]) + Math.abs(matrix[10]),
      ),
  ];
  return [...center, ...size].every(Number.isFinite)
    ? { center, size }
    : undefined;
}

export const PLAYBACK_RESIDENCY_HORIZONTAL_CELL = 128;
export const PLAYBACK_RESIDENCY_VERTICAL_CELL = 16;

/** Coarse focus changes keep playback residency selection off the frame loop. */
export function playbackFormationResidencyFocusCell(
  position: WorldNavigationVec3,
): { key: string; focus: WorldNavigationVec3 } {
  const finitePosition =
    Array.isArray(position) &&
    position.length === 3 &&
    position.every(Number.isFinite)
      ? position
      : ([0, 0.5, 5] as const);
  const xCell = Math.floor(
    finitePosition[0] / PLAYBACK_RESIDENCY_HORIZONTAL_CELL,
  );
  const yCell = Math.floor(
    finitePosition[1] / PLAYBACK_RESIDENCY_VERTICAL_CELL,
  );
  const zCell = Math.floor(
    finitePosition[2] / PLAYBACK_RESIDENCY_HORIZONTAL_CELL,
  );
  return {
    key: `${xCell}:${yCell}:${zCell}`,
    focus: [
      (xCell + 0.5) * PLAYBACK_RESIDENCY_HORIZONTAL_CELL,
      (yCell + 0.5) * PLAYBACK_RESIDENCY_VERTICAL_CELL,
      (zCell + 0.5) * PLAYBACK_RESIDENCY_HORIZONTAL_CELL,
    ],
  };
}

export type FormationResidencyPresentationCandidate = Readonly<{
  id: string;
  stage: Entity["stage"];
  recipeIdentity: string;
  completedRecipeIdentity?: string;
  /** A resolved, finite world-space center is required to place a proxy. */
  worldCenter?: WorldNavigationVec3;
}>;

export type FormationResidencyPresentationOptions = Readonly<{
  candidates: readonly FormationResidencyPresentationCandidate[];
  focus: WorldNavigationVec3;
  visibleIds?: ReadonlySet<string>;
  selectedId?: string;
  previousResidentIds?: ReadonlySet<string>;
  maxResidents?: number;
  enabled?: boolean;
}>;

export type FormationResidencyPresentation = Readonly<{
  /** Formations that must stay mounted, including pending and unknown bounds. */
  fullFormationIds: ReadonlySet<string>;
  /** Completed, nonresident entities represented by cheap renderer proxies. */
  proxyIds: ReadonlySet<string>;
  /** Completed recipes admitted to the bounded full-resource budget. */
  residentIds: ReadonlySet<string>;
  selection: FormationResidencySelection;
}>;

const EMPTY_SELECTION = selectFormationResidents({
  candidates: [],
  focus: [0, 0, 0],
});

/**
 * Applies the residency budget only to ready, completed recipes with a usable
 * proxy center. Every other entity stays on the full Formation path.
 */
export function selectFormationResidencyPresentation(
  options: FormationResidencyPresentationOptions,
): FormationResidencyPresentation {
  const fullFormationIds = new Set<string>();
  const eligible: FormationResidencyPresentationCandidate[] = [];

  for (const candidate of options.candidates) {
    const hasFiniteCenter =
      Array.isArray(candidate.worldCenter) &&
      candidate.worldCenter.length === 3 &&
      candidate.worldCenter.every(Number.isFinite);
    if (
      !options.enabled ||
      candidate.stage !== "ready" ||
      candidate.completedRecipeIdentity !== candidate.recipeIdentity ||
      !hasFiniteCenter
    ) {
      fullFormationIds.add(candidate.id);
      continue;
    }
    eligible.push(candidate);
  }

  if (!options.enabled) {
    return {
      fullFormationIds,
      proxyIds: new Set(),
      residentIds: new Set(),
      selection: EMPTY_SELECTION,
    };
  }

  const selection = selectFormationResidents({
    candidates: eligible.map(({ id, stage, worldCenter }) => ({
      id,
      stage,
      worldCenter,
    })),
    focus: options.focus,
    visibleIds: options.visibleIds,
    selectedIds: options.selectedId ? new Set([options.selectedId]) : undefined,
    previousResidentIds: options.previousResidentIds,
    maxResidents: options.maxResidents,
  });
  for (const id of selection.residentIds) fullFormationIds.add(id);

  return {
    fullFormationIds,
    proxyIds: selection.placeholderIds,
    residentIds: selection.residentIds,
    selection,
  };
}

src/lib/formation-completion.ts:
import type { Entity } from "./protocol";

export type FormationCompletionRecords = Map<string, Map<string, string>>;

function canonicalRecipeValue(value: unknown): string {
  if (Array.isArray(value))
    return `[${value.map(canonicalRecipeValue).join(",")}]`;
  if (value !== null && typeof value === "object") {
    const record = value as Record<string, unknown>;
    return `{${Object.keys(record)
      .filter((key) => record[key] !== undefined)
      .sort()
      .map(
        (key) => `${JSON.stringify(key)}:${canonicalRecipeValue(record[key])}`,
      )
      .join(",")}}`;
  }
  return JSON.stringify(value) ?? "undefined";
}

/** Stable across project revisions and object key order; covers rendered inputs. */
export function formationRecipeIdentity(
  entity: Pick<Entity, "geometry" | "color">,
): string {
  return canonicalRecipeValue([entity.geometry ?? null, entity.color]);
}

export function formationResourceMatchesRecipe(
  resourceRecipeIdentity: string | undefined,
  recipeIdentity: string,
): boolean {
  return resourceRecipeIdentity === recipeIdentity;
}

export function formationCanHydrateComplete(
  records: ReadonlyMap<string, ReadonlyMap<string, string>>,
  projectId: string,
  entityId: string,
  recipeIdentity: string,
  resourceRecipeIdentity: string | undefined,
  stage: Entity["stage"],
  pending: boolean,
  failed: boolean,
): boolean {
  return (
    stage === "ready" &&
    formationResourceMatchesRecipe(resourceRecipeIdentity, recipeIdentity) &&
    !pending &&
    !failed &&
    records.get(projectId)?.get(entityId) === recipeIdentity
  );
}

export function markFormationComplete(
  records: FormationCompletionRecords,
  projectId: string,
  entityId: string,
  recipeIdentity: string,
  resourceRecipeIdentity: string | undefined,
  stage: Entity["stage"],
  pending: boolean,
  failed: boolean,
  progress: number,
): boolean {
  if (
    stage !== "ready" ||
    !formationResourceMatchesRecipe(resourceRecipeIdentity, recipeIdentity) ||
    pending ||
    failed ||
    !Number.isFinite(progress) ||
    progress < 1
  )
    return false;
  let projectRecords = records.get(projectId);
  if (!projectRecords) {
    projectRecords = new Map();
    records.set(projectId, projectRecords);
  }
  if (projectRecords.get(entityId) === recipeIdentity) return true;
  projectRecords.set(entityId, recipeIdentity);
  return true;
}

export function reconcileFormationCompletionRecords(
  records: FormationCompletionRecords,
  projectId: string,
  recipeByEntity: ReadonlyMap<string, string>,
): void {
  for (const id of records.keys()) if (id !== projectId) records.delete(id);
  let projectRecords = records.get(projectId);
  if (!projectRecords) {
    projectRecords = new Map();
    records.set(projectId, projectRecords);
  }
  for (const [entityId, recipeIdentity] of projectRecords)
    if (recipeByEntity.get(entityId) !== recipeIdentity)
      projectRecords.delete(entityId);
}

src/lib/world-terrain.ts:
import {
  WORLD_NAVIGATION_CAMERA_ELEVATION_RADIANS,
  WORLD_NAVIGATION_LIMITS,
} from "./world-navigation";

export type WorldTerrainChunkKey = Readonly<{
  lod: number;
  x: number;
  z: number;
}>;

export type WorldTerrainFocus = readonly [x: number, y: number, z: number];

export type WorldTerrainView = Readonly<{
  /** World-space camera/player focus; terrain selection uses X/Z and height. */
  focus: WorldTerrainFocus;
  /** Camera distance along the shared 30-degree camera pose. */
  distance: number;
  /** Viewport width divided by height. */
  aspect: number;
}>;

export type WorldTerrainSample = Readonly<{
  position: readonly [x: number, y: 0, z: number];
  /** Smooth, deterministic normalized appearance variation in [0, 1]. */
  appearance: number;
}>;

export const WORLD_TERRAIN_BASE_CHUNK_SIZE = 64;
export const WORLD_TERRAIN_NEIGHBORHOOD_RADIUS = 3;
export const WORLD_TERRAIN_MAX_ACTIVE_CHUNKS =
  (WORLD_TERRAIN_NEIGHBORHOOD_RADIUS * 2 + 1) ** 2;
export const WORLD_TERRAIN_COLLISION_HEIGHT = 0;
export const WORLD_TERRAIN_VERTICAL_FOV_RADIANS = (43 * Math.PI) / 180;

const MAX_TERRAIN_LOD = 40;
const MIN_SUPPORTED_ASPECT = 0.05;
const MAX_SUPPORTED_ASPECT = 20;
const VERTICAL_TANGENT = Math.tan(WORLD_TERRAIN_VERTICAL_FOV_RADIANS / 2);

function finiteWorldCoordinate(value: number) {
  return (
    Number.isFinite(value) &&
    Math.abs(value) <= WORLD_NAVIGATION_LIMITS.maxTargetCoordinate
  );
}

function assertView(distance: number, aspect: number) {
  if (
    !Number.isFinite(distance) ||
    distance < WORLD_NAVIGATION_LIMITS.minDistance ||
    distance > WORLD_NAVIGATION_LIMITS.maxDistance
  )
    throw new RangeError(
      "Terrain camera distance is outside supported limits.",
    );
  if (
    !Number.isFinite(aspect) ||
    aspect < MIN_SUPPORTED_ASPECT ||
    aspect > MAX_SUPPORTED_ASPECT
  )
    throw new RangeError(
      "Terrain viewport aspect is outside supported limits.",
    );
}

function assertFocus(
  focus: WorldTerrainFocus,
): asserts focus is WorldTerrainFocus {
  if (
    !Array.isArray(focus) ||
    focus.length !== 3 ||
    !finiteWorldCoordinate(focus[0]) ||
    !finiteWorldCoordinate(focus[1]) ||
    !finiteWorldCoordinate(focus[2])
  )
    throw new RangeError(
      "Terrain focus must be finite and within world limits.",
    );
}

/** Return the exact power-of-two chunk edge length for a non-negative LOD. */
export function worldTerrainChunkSize(lod: number): number {
  if (!Number.isSafeInteger(lod) || lod < 0 || lod > MAX_TERRAIN_LOD)
    throw new RangeError("Terrain LOD is outside supported limits.");
  return WORLD_TERRAIN_BASE_CHUNK_SIZE * Math.pow(2, lod);
}

/** Map world X/Z to a signed chunk key using floor semantics at negative edges. */
export function worldTerrainChunkKeyAt(
  x: number,
  z: number,
  lod = 0,
): WorldTerrainChunkKey {
  const size = worldTerrainChunkSize(lod);
  if (!finiteWorldCoordinate(x) || !finiteWorldCoordinate(z))
    throw new RangeError("Terrain coordinates must be finite and in range.");
  const chunkX = Math.floor(x / size);
  const chunkZ = Math.floor(z / size);
  return {
    lod,
    x: Object.is(chunkX, -0) ? 0 : chunkX,
    z: Object.is(chunkZ, -0) ? 0 : chunkZ,
  };
}

/**
 * Maximum distance from the focus to a point where a viewport corner ray
 * intersects the flat ground. This uses the shared 43-degree FOV and camera
 * elevation; the symmetric footprint is heading-independent.
 */
export function worldTerrainGroundViewRadius(
  distance: number,
  aspect: number,
  focusHeight = 0,
): number {
  assertView(distance, aspect);
  if (!finiteWorldCoordinate(focusHeight))
    throw new RangeError("Terrain focus height must be finite and in range.");
  const elevation = WORLD_NAVIGATION_CAMERA_ELEVATION_RADIANS;
  const sinElevation = Math.sin(elevation);
  const cosElevation = Math.cos(elevation);
  const cameraHeight = focusHeight + distance * sinElevation;
  // When framing an authored object below the ground, the downward-looking
  // camera cannot see the y=0 plane. Keep chunk selection bounded instead of
  // letting the renderer fail for an otherwise valid world-space target.
  if (!(cameraHeight > 0)) return 0;
  const cameraForward = distance * cosElevation;
  const horizontalTangent = VERTICAL_TANGENT * aspect;
  let maxRadius = 0;

  for (const vertical of [-VERTICAL_TANGENT, VERTICAL_TANGENT]) {
    const rayY = -sinElevation + vertical * cosElevation;
    if (!(rayY < 0))
      throw new RangeError("The shared terrain camera must face the ground.");
    const scale = -cameraHeight / rayY;
    const rayZ = -cosElevation - vertical * sinElevation;
    for (const horizontal of [-horizontalTangent, horizontalTangent]) {
      const x = scale * horizontal;
      const z = cameraForward + scale * rayZ;
      const radius = Math.hypot(x, z);
      if (!Number.isFinite(radius))
        throw new RangeError("Terrain view footprint is not finite.");
      maxRadius = Math.max(maxRadius, radius);
    }
  }
  return maxRadius;
}

/**
 * Select a fixed 7x7 world-aligned neighborhood around an explicit focus.
 * LOD is the smallest power-of-two tile size whose neighborhood contains the
 * complete ground-plane viewport footprint.
 */
export function selectWorldTerrainChunks(
  view: WorldTerrainView,
): readonly WorldTerrainChunkKey[] {
  if (!view || typeof view !== "object")
    throw new RangeError("Terrain view is required.");
  assertFocus(view.focus);
  const radius = worldTerrainGroundViewRadius(
    view.distance,
    view.aspect,
    view.focus[1],
  );
  let lod = 0;
  let size = worldTerrainChunkSize(lod);
  while (
    WORLD_TERRAIN_NEIGHBORHOOD_RADIUS * size < radius &&
    lod < MAX_TERRAIN_LOD
  ) {
    lod += 1;
    size = worldTerrainChunkSize(lod);
  }
  if (WORLD_TERRAIN_NEIGHBORHOOD_RADIUS * size < radius)
    throw new RangeError("Terrain footprint exceeds supported chunk LOD.");

  const center = worldTerrainChunkKeyAt(view.focus[0], view.focus[2], lod);
  const chunks: WorldTerrainChunkKey[] = [];
  for (
    let z = center.z - WORLD_TERRAIN_NEIGHBORHOOD_RADIUS;
    z <= center.z + WORLD_TERRAIN_NEIGHBORHOOD_RADIUS;
    z += 1
  ) {
    for (
      let x = center.x - WORLD_TERRAIN_NEIGHBORHOOD_RADIUS;
      x <= center.x + WORLD_TERRAIN_NEIGHBORHOOD_RADIUS;
      x += 1
    )
      chunks.push({ lod, x, z });
  }
  return chunks;
}

/** Sample a seamless world-space appearance value; LOD and chunk keys are irrelevant. */
export function sampleWorldTerrainAppearance(x: number, z: number): number {
  if (!Number.isFinite(x) || !Number.isFinite(z))
    throw new RangeError("Terrain sample coordinates must be finite.");
  const broad = Math.sin(x * 0.0017 + z * 0.0011);
  const medium = Math.sin(x * 0.017 - z * 0.013) * Math.cos(z * 0.019);
  const fine = Math.sin(z * 0.071 + x * 0.043);
  return 0.5 + 0.2 * broad + 0.15 * medium + 0.1 * fine;
}

/**
 * Sample a chunk-local normalized point. Adjacent keys produce the same
 * world coordinate on their shared edge, including after LOD changes.
 */
export function sampleWorldTerrainChunk(
  key: WorldTerrainChunkKey,
  u: number,
  v: number,
): WorldTerrainSample {
  if (!key || !Number.isSafeInteger(key.x) || !Number.isSafeInteger(key.z))
    throw new RangeError("Terrain chunk coordinates must be safe integers.");
  const size = worldTerrainChunkSize(key.lod);
  if (!Number.isFinite(u) || u < 0 || u > 1)
    throw new RangeError("Terrain chunk U coordinate must be in [0, 1].");
  if (!Number.isFinite(v) || v < 0 || v > 1)
    throw new RangeError("Terrain chunk V coordinate must be in [0, 1].");
  const x = key.x * size + u * size;
  const z = key.z * size + v * size;
  if (!Number.isFinite(x) || !Number.isFinite(z))
    throw new RangeError("Terrain sample position is not finite.");
  return {
    position: [x, WORLD_TERRAIN_COLLISION_HEIGHT, z],
    appearance: sampleWorldTerrainAppearance(x, z),
  };
}

src/lib/scene-support.ts:
import { Matrix4, Vector3 } from "three";

type Point = readonly [number, number, number];
export type SupportBounds = { min: Point; max: Point };
const EPSILON = 1e-9;

function usable(matrix: Matrix4) {
  return (
    matrix.elements.every(Number.isFinite) &&
    matrix.elements[3] === 0 &&
    matrix.elements[7] === 0 &&
    matrix.elements[11] === 0 &&
    matrix.elements[15] === 1 &&
    Number.isFinite(matrix.determinant()) &&
    matrix.determinant() !== 0
  );
}

/** Vertical ray against the transformed box, including rotated/sheared faces.
 * Returns the upper surface, not the top of its world-axis-aligned bounds.
 * Bounds remain a collision proxy, as in the existing platform contract.
 */
export function supportSurfaceHeight(
  matrix: Matrix4,
  bounds: SupportBounds,
  x: number,
  z: number,
): number | undefined {
  if (
    !usable(matrix) ||
    !Number.isFinite(x) ||
    !Number.isFinite(z) ||
    ![...bounds.min, ...bounds.max].every(Number.isFinite) ||
    bounds.min.some((v, axis) => v > bounds.max[axis])
  )
    return undefined;
  const inverse = matrix.clone().invert();
  const origin = new Vector3(x, 0, z).applyMatrix4(inverse);
  // Transform a direction without normalization: t must remain world height.
  const direction = new Vector3(
    inverse.elements[4],
    inverse.elements[5],
    inverse.elements[6],
  );
  let enter = -Infinity;
  let leave = Infinity;
  for (let axis = 0; axis < 3; axis++) {
    const start = origin.getComponent(axis);
    const delta = direction.getComponent(axis);
    if (delta === 0) {
      if (
        start < bounds.min[axis] - EPSILON ||
        start > bounds.max[axis] + EPSILON
      )
        return undefined;
      continue;
    }
    const a = (bounds.min[axis] - start) / delta;
    const b = (bounds.max[axis] - start) / delta;
    enter = Math.max(enter, Math.min(a, b));
    leave = Math.min(leave, Math.max(a, b));
    if (enter > leave + EPSILON) return undefined;
  }
  return Number.isFinite(leave) ? leave : undefined;
}

/** Carry an existing world contact through an exact support pose change. */
export function carrySupportContact(
  previous: Matrix4,
  next: Matrix4,
  contact: Point,
): [number, number, number] | undefined {
  if (!usable(previous) || !usable(next) || !contact.every(Number.isFinite))
    return undefined;
  const result = new Vector3(...contact)
    .applyMatrix4(previous.clone().invert())
    .applyMatrix4(next);
  return result.toArray().every(Number.isFinite) ? result.toArray() : undefined;
}

