import type { Entity } from "./protocol";
import { gameplayEntityForVisualState } from "./gameplay";

export type DisplayedGameplayRecipe = Pick<Entity, "geometry" | "stage"> & {
  recipeIdentity: string;
};
export type DisplayedGameplayRecipeRegistry = Map<
  string,
  DisplayedGameplayRecipe
>;
export type DisplayedGameplayRecipeScope = {
  projectId: string;
  registry: DisplayedGameplayRecipeRegistry;
};

/** Starts a fresh per-project registry before children can commit resources. */
export function displayedGameplayRecipeScopeForProject(
  scope: DisplayedGameplayRecipeScope,
  projectId: string,
): DisplayedGameplayRecipeScope {
  return scope.projectId === projectId
    ? scope
    : { projectId, registry: new Map() };
}

/** Records only recipes whose Formation resource has committed to the scene. */
export function recordDisplayedGameplayRecipe(
  registry: DisplayedGameplayRecipeRegistry,
  entity: Pick<Entity, "id" | "geometry" | "stage">,
  recipeIdentity: string,
): void {
  const current = registry.get(entity.id);
  if (
    current?.recipeIdentity === recipeIdentity &&
    current.stage === entity.stage &&
    current.geometry === entity.geometry
  )
    return;
  registry.set(entity.id, {
    geometry: entity.geometry,
    stage: entity.stage,
    recipeIdentity,
  });
}

/** Resolves a per-entity displayed recipe without sharing readiness by asset ID. */
export function gameplayEntityFromDisplayedRecipe(
  entity: Entity,
  registry: ReadonlyMap<string, DisplayedGameplayRecipe>,
  currentRecipeIdentity: string,
): Entity {
  const displayed = registry.get(entity.id);
  const displayedRecipeIsCurrent =
    displayed?.recipeIdentity === currentRecipeIdentity &&
    displayed.stage === entity.stage;
  return gameplayEntityForVisualState(
    entity,
    displayedRecipeIsCurrent,
    displayed,
  );
}

/** True only when the committed visual is the current ready objective recipe. */
export function displayedGameplayRecipeMatchesCurrent(
  displayed: DisplayedGameplayRecipe | undefined,
  currentRecipeIdentity: string | undefined,
  currentStage: Entity["stage"] | undefined,
): boolean {
  return (
    currentStage === "ready" &&
    displayed?.stage === "ready" &&
    displayed.recipeIdentity === currentRecipeIdentity
  );
}

src/lib/gameplay-observation.ts:
import type { GameProgramStatus } from "./game-program";
import type { PlayerState, Vec3 } from "./gameplay";

export type GameplayObservationEntity = {
  id: string;
  behavior: string | null;
  stage: string;
  position: Vec3;
  scale: Vec3;
};

export type GameplayObservation = {
  renderer: "webgl" | "software";
  projectId: string;
  revision: number;
  atMs: number;
  simulationDeltaMs: number;
  playing: boolean;
  player: {
    position: Vec3;
    velocityY: number;
    groundedOn?: string;
    supportPosition?: Vec3;
  };
  entities: GameplayObservationEntity[];
  contacts: string[];
  platformContacts: string[];
  bounceContacts: string[];
  platformContactCounts: Record<string, number>;
  bounceContactCounts: Record<string, number>;
  collected: string[];
  scoreIds: string[];
  gameScore: number;
  status: GameProgramStatus | null;
  won: boolean;
  lost: boolean;
  reset: number;
  sessionGeneration: number;
};

type GameplayObservationGlobal = typeof globalThis & {
  __ORBSIE_GAMEPLAY_READ_REQUESTED__?: boolean;
  __ORBSIE_GAMEPLAY_READ__?: () => GameplayObservation;
};

type GameplayObservationInput = Omit<
  GameplayObservation,
  | "atMs"
  | "platformContacts"
  | "bounceContacts"
  | "platformContactCounts"
  | "bounceContactCounts"
> & {
  platformContactId?: string;
  bounceContactId?: string;
};

let accumulatorKey = "";
let platformContactCounts: Record<string, number> = Object.create(null);
let bounceContactCounts: Record<string, number> = Object.create(null);
const MAX_CONTACT_EVENTS = 4096;

export function gameplayObservationRequested(): boolean {
  return (
    (globalThis as GameplayObservationGlobal)
      .__ORBSIE_GAMEPLAY_READ_REQUESTED__ === true
  );
}

/**
 * Publish copied primitive state for the opt-in browser acceptance harness.
 * The callback closes over no store, session, geometry, or mutator.
 */
export function publishGameplayObservation(
  value: GameplayObservationInput,
): void {
  const target = globalThis as GameplayObservationGlobal;
  if (target.__ORBSIE_GAMEPLAY_READ_REQUESTED__ !== true) return;
  const nextKey = [
    value.projectId,
    value.revision,
    value.renderer,
    value.reset,
    value.sessionGeneration,
  ].join(":");
  if (nextKey !== accumulatorKey) {
    accumulatorKey = nextKey;
    platformContactCounts = Object.create(null);
    bounceContactCounts = Object.create(null);
  }
  if (value.platformContactId)
    platformContactCounts[value.platformContactId] = Math.min(
      MAX_CONTACT_EVENTS,
      (platformContactCounts[value.platformContactId] ?? 0) + 1,
    );
  if (value.bounceContactId)
    bounceContactCounts[value.bounceContactId] = Math.min(
      MAX_CONTACT_EVENTS,
      (bounceContactCounts[value.bounceContactId] ?? 0) + 1,
    );
  const copyPlayer = (player: PlayerState) => ({
    position: [...player.position] as Vec3,
    velocityY: player.velocityY,
    ...(player.groundedOn ? { groundedOn: player.groundedOn } : {}),
    ...(player.supportPosition
      ? { supportPosition: [...player.supportPosition] as Vec3 }
      : {}),
  });
  const { platformContactId, bounceContactId, ...base } = value;
  const snapshot: GameplayObservation = {
    ...base,
    atMs: performance.now(),
    player: copyPlayer(value.player),
    entities: value.entities.map((entity) => ({
      ...entity,
      position: [...entity.position] as Vec3,
      scale: [...entity.scale] as Vec3,
    })),
    contacts: [...value.contacts],
    platformContacts: platformContactId ? [platformContactId] : [],
    bounceContacts: bounceContactId ? [bounceContactId] : [],
    platformContactCounts: Object.assign(
      Object.create(null),
      platformContactCounts,
    ),
    bounceContactCounts: Object.assign(
      Object.create(null),
      bounceContactCounts,
    ),
    collected: [...value.collected],
    scoreIds: [...value.scoreIds],
  };
  const freeze = (entry: unknown): unknown => {
    if (entry && typeof entry === "object" && !Object.isFrozen(entry)) {
      Object.freeze(entry);
      for (const child of Object.values(entry)) freeze(child);
    }
    return entry;
  };
  freeze(snapshot);
  target.__ORBSIE_GAMEPLAY_READ__ = () => snapshot;
}

src/lib/software-formation-residency.ts:
import type { Entity } from "./protocol";
import {
  selectFormationResidencyPresentation,
  type FormationResidencyPresentation,
} from "./formation-residency-presentation";
import { formationRecipeIdentity } from "./formation-completion";
import type { FormationProxyVisualBounds } from "./formation-residency-presentation";
import type { WorldNavigationVec3 } from "./world-navigation";

export type SoftwareFormationResidencyOptions = Readonly<{
  entities: readonly Entity[];
  completedRecipeByEntity: ReadonlyMap<string, string>;
  proxyBoundsByEntity: ReadonlyMap<
    string,
    FormationProxyVisualBounds | undefined
  >;
  focus: WorldNavigationVec3;
  visibleIds?: ReadonlySet<string>;
  selectedId?: string;
  previousResidentIds?: ReadonlySet<string>;
  enabled?: boolean;
}>;

/** Keep only completed current recipes eligible for the software proxy path. */
export function selectSoftwareFormationResidency(
  options: SoftwareFormationResidencyOptions,
): FormationResidencyPresentation {
  return selectFormationResidencyPresentation({
    candidates: options.entities.map((entity) => ({
      id: entity.id,
      stage: entity.stage,
      recipeIdentity: formationRecipeIdentity(entity),
      completedRecipeIdentity: options.completedRecipeByEntity.get(entity.id),
      worldCenter: options.proxyBoundsByEntity.get(entity.id)?.center,
    })),
    focus: options.focus,
    visibleIds: options.visibleIds,
    selectedId: options.selectedId,
    previousResidentIds: options.previousResidentIds,
    enabled: options.enabled,
  });
}

export type SoftwareDisplayedGeometry = Readonly<{
  ready: boolean;
  sourceRecipe: Entity["geometry"];
  sourceStage: Entity["stage"];
  sourceColor?: string;
}>;

export function softwareActiveProxyIds(
  options: Readonly<{
    entities: readonly Entity[];
    presentation: Pick<
      FormationResidencyPresentation,
      "proxyIds" | "residentIds"
    >;
    completedRecipeByEntity: ReadonlyMap<string, string>;
    displayedByEntity: ReadonlyMap<
      string,
      SoftwareDisplayedGeometry | undefined
    >;
  }>,
): ReadonlySet<string> {
  const proxyIds = new Set(options.presentation.proxyIds);
  for (const entity of options.entities) {
    if (
      options.presentation.residentIds.has(entity.id) &&
      options.completedRecipeByEntity.get(entity.id) ===
        formationRecipeIdentity(entity) &&
      !softwareGeometryMatchesEntity(
        entity,
        options.displayedByEntity.get(entity.id),
      )
    )
      proxyIds.add(entity.id);
  }
  return proxyIds;
}

export type SoftwareProxyDrawRecord = Readonly<{
  projectId: string;
  revision: number;
  recipeIdentity: string;
}>;

export type SoftwareFormationCompletionRecord = {
  recipeIdentity: string;
  loadedRevision: number;
  fullDrawnRevision?: number;
};

export function softwareProxyDrawnForRevision(
  entity: Entity,
  projectId: string,
  revision: number,
  record: SoftwareProxyDrawRecord | undefined,
): boolean {
  return Boolean(
    record !== undefined &&
    record.projectId === projectId &&
    record.revision === revision &&
    record.recipeIdentity === formationRecipeIdentity(entity),
  );
}

export function softwareGeometryMatchesEntity(
  entity: Entity,
  entry: SoftwareDisplayedGeometry | undefined,
): boolean {
  return Boolean(
    entry?.ready &&
    entry.sourceRecipe === entity.geometry &&
    entry.sourceStage === entity.stage &&
    (entry.sourceColor === undefined || entry.sourceColor === entity.color),
  );
}

/** A proxy is review-ready only when its recorded completed recipe still matches. */
export function softwareEntityVisualReviewReady(
  entity: Entity,
  entry: SoftwareDisplayedGeometry | undefined,
  completion: SoftwareFormationCompletionRecord | undefined,
  currentRevision: number,
  visibleInViewport = true,
  proxyRepresentation = false,
  proxyVisible = false,
  proxyDrawnForRevision = false,
): boolean {
  const currentRecipeIdentity = formationRecipeIdentity(entity);
  const completedCurrentRecipe =
    completion?.recipeIdentity === currentRecipeIdentity;
  if (!completedCurrentRecipe) return false;
  if (softwareGeometryMatchesEntity(entity, entry))
    return (
      !visibleInViewport || completion.fullDrawnRevision === currentRevision
    );
  return (
    proxyRepresentation &&
    entity.stage === "ready" &&
    (!proxyVisible || proxyDrawnForRevision)
  );
}

/** Release only the geometry owned by this lease; stale cleanup cannot evict a newer entry. */
export function releaseOwnedSoftwareGeometry<
  TGeometry,
  TEntry extends Readonly<{ geometry: TGeometry }>,
>(
  entries: Map<string, TEntry>,
  entityId: string,
  ownedGeometry: TGeometry | undefined,
  dispose: (geometry: TGeometry) => void,
): boolean {
  if (ownedGeometry === undefined) return false;
  const current = entries.get(entityId);
  if (current?.geometry === ownedGeometry) {
    entries.delete(entityId);
    dispose(ownedGeometry);
    return true;
  }
  dispose(ownedGeometry);
  return false;
}

